package com.bigboldchat.chat;

import net.runelite.api.FontTypeFace;

import org.junit.Before;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import static org.mockito.ArgumentMatchers.anyString;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.when;

/**
 * Characterization tests for the Chat XL measurement service.
 */
public class FontMeasurementServiceTest
{
    private FontMeasurementService service;

    @Before
    public void setUp()
    {
        /*
         * The supported-script and wrapping contracts do not access
         * Client state.
         */
        service =
                new FontMeasurementService(
                        null);
    }

    /*
     * ================================================================
     * SCRIPT SUPPORT
     * ================================================================
     */

    @Test
    public void supportsOnlyKnownChatConstructionScripts()
    {
        assertTrue(
                service.supportsScript(
                        199));

        assertTrue(
                service.supportsScript(
                        203));

        assertTrue(
                service.supportsScript(
                        4483));

        assertFalse(
                service.supportsScript(
                        -1));

        assertFalse(
                service.supportsScript(
                        0));

        assertFalse(
                service.supportsScript(
                        72));

        assertFalse(
                service.supportsScript(
                        193));

        assertFalse(
                service.supportsScript(
                        4482));

        assertFalse(
                service.supportsScript(
                        4484));
    }

    /*
     * ================================================================
     * SINGLE-PARAGRAPH WRAPPING
     * ================================================================
     */

    @Test
    public void oversizedLettersRemainOneTokenLine()
    {
        final FontTypeFace font =
                fixedWidthFont(
                        10);

        final int lines =
                service.calculateSingleParagraphLines(
                        font,
                        "aaaaaaaaaa",
                        40);

        assertEquals(
                1,
                lines);
    }

    @Test
    public void oversizedNumbersRemainOneTokenLine()
    {
        final FontTypeFace font =
                fixedWidthFont(
                        10);

        final int lines =
                service.calculateSingleParagraphLines(
                        font,
                        "1111111111",
                        40);

        assertEquals(
                1,
                lines);
    }

    @Test
    public void oversizedHashRunRemainsOneTokenLine()
    {
        final FontTypeFace font =
                fixedWidthFont(
                        10);

        final int lines =
                service.calculateSingleParagraphLines(
                        font,
                        "##########",
                        40);

        assertEquals(
                1,
                lines);
    }

    @Test
    public void oversizedCaretRunRemainsOneTokenLine()
    {
        final FontTypeFace font =
                fixedWidthFont(
                        10);

        final int lines =
                service.calculateSingleParagraphLines(
                        font,
                        "^^^^^^^^^^",
                        40);

        assertEquals(
                1,
                lines);
    }

    @Test
    public void oversizedAtRunRemainsOneTokenLine()
    {
        final FontTypeFace font =
                fixedWidthFont(
                        10);

        final int lines =
                service.calculateSingleParagraphLines(
                        font,
                        "@@@@@@@@@@",
                        40);

        assertEquals(
                1,
                lines);
    }

    @Test
    public void oversizedMixedSymbolRunRemainsOneTokenLine()
    {
        final FontTypeFace font =
                fixedWidthFont(
                        10);

        final int lines =
                service.calculateSingleParagraphLines(
                        font,
                        "#^%&*!@#$^",
                        40);

        assertEquals(
                1,
                lines);
    }

    @Test
    public void oversizedTokenFollowedByNormalWordStartsNextLine()
    {
        final FontTypeFace font =
                fixedWidthFont(
                        10);

        final int lines =
                service.calculateSingleParagraphLines(
                        font,
                        "########## hi",
                        40);

        assertEquals(
                2,
                lines);
    }

    @Test
    public void normalWordsStillWrapByAvailableWidth()
    {
        final FontTypeFace font =
                fixedWidthFont(
                        10);

        /*
         * "aa bb" = 5 characters = 50px.
         *
         * "aa bb cc" = 8 characters = 80px.
         *
         * With a 50px row:
         *
         *     line 1: aa bb
         *     line 2: cc
         */
        final int lines =
                service.calculateSingleParagraphLines(
                        font,
                        "aa bb cc",
                        50);

        assertEquals(
                2,
                lines);
    }

    @Test
    public void normalWordsRemainOneLineWhenTheyFit()
    {
        final FontTypeFace font =
                fixedWidthFont(
                        10);

        final int lines =
                service.calculateSingleParagraphLines(
                        font,
                        "aa bb",
                        50);

        assertEquals(
                1,
                lines);
    }

    @Test
    public void oversizedTokenBetweenNormalWordsPreservesLineBoundaries()
    {
        final FontTypeFace font =
                fixedWidthFont(
                        10);

        /*
         * "hi" fits.
         *
         * The oversized token cannot join "hi", so it starts the next
         * logical line.
         *
         * "bye" cannot join the oversized token, so it starts another.
         */
        final int lines =
                service.calculateSingleParagraphLines(
                        font,
                        "hi ########## bye",
                        40);

        assertEquals(
                3,
                lines);
    }

    /*
     * ================================================================
     * HELPERS
     * ================================================================
     */

    private FontTypeFace fixedWidthFont(
            int characterWidth)
    {
        final FontTypeFace font =
                mock(
                        FontTypeFace.class);

        when(font.getTextWidth(
                anyString()))
                .thenAnswer(
                        invocation ->
                        {
                            final String text =
                                    invocation.getArgument(
                                            0);

                            return text.length()
                                    * characterWidth;
                        });

        return font;
    }
}

package com.bigboldchat.chat;

import com.bigboldchat.Configurations;
import com.bigboldchat.config.ChatFont;
import com.bigboldchat.debug.PerformanceMetrics;
import com.bigboldchat.fonts.ChatFontProfile;
import com.bigboldchat.fonts.ChatFontRegistry;

import java.util.Arrays;
import java.util.List;
import java.util.concurrent.atomic.AtomicInteger;

import net.runelite.api.Client;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.Widget;

import org.junit.Before;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertSame;
import static org.junit.Assert.assertTrue;
import static org.mockito.Mockito.doAnswer;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.never;
import static org.mockito.Mockito.times;
import static org.mockito.Mockito.verify;
import static org.mockito.Mockito.when;

/**
 * Characterization tests for Chat XL layout, presentation, and correlation.
 *
 * These tests protect:
 *
 *  - row-first / lazy-fallback text correlation;
 *  - row-first rank correlation, shallow refresh, and recursive correctness fallback;
 *  - active font/profile lifecycle;
 *  - idempotent widget mutation;
 *  - conditional widget revalidation;
 *  - FontLayoutService integration with the persistent row index.
 *
 * The test class deliberately uses package-private test seams instead of
 * Java reflection.
 */
public class FontLayoutServiceTest
{
    private Client client;

    private Configurations config;

    private PerformanceMetrics performanceMetrics;

    private FontLayoutService service;

    @Before
    public void setUp()
    {
        client =
                mock(
                        Client.class);

        config =
                mock(
                        Configurations.class);

        when(config.chatFont())
                .thenReturn(
                        ChatFont.PLAIN_12);

        performanceMetrics =
                new PerformanceMetrics();

        service =
                new FontLayoutService(
                        client,
                        config,
                        new FontMeasurementService(
                                client),
                        new ChatTextNormalizer(
                                performanceMetrics),
                        performanceMetrics);
    }

    /*
     * ================================================================
     * TEXT CORRELATION
     * ================================================================
     */

    @Test
    public void rowFirstMatchDoesNotBuildFallback()
    {
        final Widget lineWidget =
                mock(
                        Widget.class);

        final Widget bodyWidget =
                mock(
                        Widget.class);

        when(bodyWidget.getText())
                .thenReturn(
                        "Test message");

        final FontLayoutService.FallbackCorrelationContext fallbackContext =
                service.new FallbackCorrelationContext(
                        FontLayoutService.Surface.CHATBOX);

        final Widget result =
                service.findTargetWidgetForLine(
                        "Test message",
                        lineWidget,
                        FontLayoutService.Surface.CHATBOX,
                        Arrays.asList(
                                lineWidget,
                                bodyWidget),
                        fallbackContext);

        assertSame(
                bodyWidget,
                result);

        /*
         * A successful row-first match must never initialize the complete
         * surface fallback index.
         */
        verify(
                client,
                never())
                .getWidget(
                        InterfaceID.Chatbox.SCROLLAREA);
    }

    @Test
    public void firstFallbackRequestBuildsSurfaceIndexOnce()
    {
        final Widget root =
                mock(
                        Widget.class);

        final Widget bodyWidget =
                mock(
                        Widget.class);

        when(bodyWidget.getText())
                .thenReturn(
                        "<col=ffffff>Test message</col>");

        when(root.getDynamicChildren())
                .thenReturn(
                        new Widget[]
                                {
                                        bodyWidget
                                });

        when(client.getWidget(
                InterfaceID.Chatbox.SCROLLAREA))
                .thenReturn(
                        root);

        final FontLayoutService.FallbackCorrelationContext fallbackContext =
                service.new FallbackCorrelationContext(
                        FontLayoutService.Surface.CHATBOX);

        final List<Widget> matches =
                fallbackContext.findMatches(
                        "Test message");

        assertEquals(
                1,
                matches.size());

        assertSame(
                bodyWidget,
                matches.get(
                        0));

        verify(
                client,
                times(
                        1))
                .getWidget(
                        InterfaceID.Chatbox.SCROLLAREA);
    }

    @Test
    public void laterFallbackRequestsReuseExistingSurfaceIndex()
    {
        final Widget root =
                mock(
                        Widget.class);

        final Widget bodyWidget =
                mock(
                        Widget.class);

        final Widget prefixWidget =
                mock(
                        Widget.class);

        when(bodyWidget.getText())
                .thenReturn(
                        "Body text");

        when(prefixWidget.getText())
                .thenReturn(
                        "Player:");

        when(root.getDynamicChildren())
                .thenReturn(
                        new Widget[]
                                {
                                        bodyWidget,
                                        prefixWidget
                                });

        when(client.getWidget(
                InterfaceID.Chatbox.SCROLLAREA))
                .thenReturn(
                        root);

        final FontLayoutService.FallbackCorrelationContext fallbackContext =
                service.new FallbackCorrelationContext(
                        FontLayoutService.Surface.CHATBOX);

        final List<Widget> bodyMatches =
                fallbackContext.findMatches(
                        "Body text");

        final List<Widget> prefixMatches =
                fallbackContext.findMatches(
                        "Player:");

        assertEquals(
                1,
                bodyMatches.size());

        assertSame(
                bodyWidget,
                bodyMatches.get(
                        0));

        assertEquals(
                1,
                prefixMatches.size());

        assertSame(
                prefixWidget,
                prefixMatches.get(
                        0));

        /*
         * Both searches must be served by one surface-index construction.
         */
        verify(
                client,
                times(
                        1))
                .getWidget(
                        InterfaceID.Chatbox.SCROLLAREA);
    }

    /*
     * ================================================================
     * RANK CORRELATION
     * ================================================================
     */

    @Test
    public void rankRowMatchDoesNotUseFallback()
    {
        final Widget root =
                mock(
                        Widget.class);

        final Widget rowAnchor =
                mock(
                        Widget.class);

        final Widget unrelatedWidget =
                mock(
                        Widget.class);

        final Widget rankWidget =
                mock(
                        Widget.class);

        when(client.getWidget(
                InterfaceID.Chatbox.SCROLLAREA))
                .thenReturn(
                        root);

        when(rowAnchor.getOriginalY())
                .thenReturn(
                        42);

        when(rowAnchor.getRelativeY())
                .thenReturn(
                        84);

        when(rankWidget.getSpriteId())
                .thenReturn(
                        1234);

        when(rankWidget.getOriginalX())
                .thenReturn(
                        27);

        when(rankWidget.getOriginalY())
                .thenReturn(
                        42);

        final FontMeasurementService.ChannelPrefixLayout nativeLayout =
                new FontMeasurementService.ChannelPrefixLayout();

        nativeLayout.rankIconSpriteId =
                1234;

        nativeLayout.rankIconX =
                27;

        final Widget result =
                service.findRankIconWidget(
                        nativeLayout,
                        rowAnchor,
                        Arrays.asList(
                                unrelatedWidget,
                                rankWidget));

        assertSame(
                rankWidget,
                result);

        /*
         * The recursive tree fallback must not be entered.
         */
        verify(
                root,
                never())
                .getDynamicChildren();

        verify(
                root,
                never())
                .getStaticChildren();

        verify(
                root,
                never())
                .getNestedChildren();
    }

    @Test
    public void rankRowMissUsesShallowRefreshBeforeRecursiveFallback()
    {
        final Widget root =
                mock(
                        Widget.class);

        final Widget rowAnchor =
                mock(
                        Widget.class);

        final Widget rowCandidate =
                mock(
                        Widget.class);

        final Widget rankWidget =
                mock(
                        Widget.class);

        when(client.getWidget(
                InterfaceID.Chatbox.SCROLLAREA))
                .thenReturn(
                        root);

        when(root.getDynamicChildren())
                .thenReturn(
                        new Widget[]
                                {
                                        rankWidget
                                });

        when(rowAnchor.getOriginalY())
                .thenReturn(
                        42);

        when(rowAnchor.getRelativeY())
                .thenReturn(
                        84);

        when(rankWidget.getSpriteId())
                .thenReturn(
                        1234);

        when(rankWidget.getOriginalX())
                .thenReturn(
                        27);

        when(rankWidget.getRelativeY())
                .thenReturn(
                        84);

        final FontMeasurementService.ChannelPrefixLayout nativeLayout =
                new FontMeasurementService.ChannelPrefixLayout();

        nativeLayout.rankIconSpriteId =
                1234;

        nativeLayout.rankIconX =
                27;

        final Widget result =
                service.findRankIconWidget(
                        nativeLayout,
                        rowAnchor,
                        Arrays.asList(
                                rowCandidate));

        assertSame(
                rankWidget,
                result);

        /*
         * A shallow match must avoid recursive traversal.
         */
        verify(
                root,
                times(
                        1))
                .getDynamicChildren();

        verify(
                root,
                never())
                .getStaticChildren();

        verify(
                root,
                never())
                .getNestedChildren();

        verify(
                rankWidget,
                never())
                .getDynamicChildren();
    }

    @Test
    public void rankShallowMissUsesRecursiveFallback()
    {
        final Widget root =
                mock(
                        Widget.class);

        final Widget rowAnchor =
                mock(
                        Widget.class);

        final Widget rowCandidate =
                mock(
                        Widget.class);

        final Widget container =
                mock(
                        Widget.class);

        final Widget rankWidget =
                mock(
                        Widget.class);

        when(client.getWidget(
                InterfaceID.Chatbox.SCROLLAREA))
                .thenReturn(
                        root);

        when(root.getDynamicChildren())
                .thenReturn(
                        new Widget[]
                                {
                                        container
                                });

        when(container.getDynamicChildren())
                .thenReturn(
                        new Widget[]
                                {
                                        rankWidget
                                });

        when(rowAnchor.getOriginalY())
                .thenReturn(
                        42);

        when(rowAnchor.getRelativeY())
                .thenReturn(
                        84);

        when(rankWidget.getSpriteId())
                .thenReturn(
                        1234);

        when(rankWidget.getOriginalX())
                .thenReturn(
                        27);

        when(rankWidget.getRelativeY())
                .thenReturn(
                        84);

        final FontMeasurementService.ChannelPrefixLayout nativeLayout =
                new FontMeasurementService.ChannelPrefixLayout();

        nativeLayout.rankIconSpriteId =
                1234;

        nativeLayout.rankIconX =
                27;

        final Widget result =
                service.findRankIconWidget(
                        nativeLayout,
                        rowAnchor,
                        Arrays.asList(
                                rowCandidate));

        assertSame(
                rankWidget,
                result);

        /*
         * The shallow scan cannot see grandchildren, so recursive fallback
         * must find the rank. The root is read once by each path.
         */
        verify(
                root,
                times(
                        2))
                .getDynamicChildren();

        verify(
                container,
                times(
                        1))
                .getDynamicChildren();
    }

    /*
     * ================================================================
     * ACTIVE FONT / PROFILE STATE
     * ================================================================
     */

    @Test
    public void activeFontStateInitializesFromConfiguration()
    {
        assertSame(
                ChatFont.PLAIN_12,
                service.activeChatFontForTesting());

        assertSame(
                ChatFontRegistry.get(
                        ChatFont.PLAIN_12),
                service.activeFontProfileForTesting());
    }

    @Test
    public void refreshActiveFontStateUpdatesProfile()
    {
        when(config.chatFont())
                .thenReturn(
                        ChatFont.BARBARIAN);

        service.refreshActiveFontState();

        assertSame(
                ChatFont.BARBARIAN,
                service.activeChatFontForTesting());

        assertSame(
                ChatFontRegistry.get(
                        ChatFont.BARBARIAN),
                service.activeFontProfileForTesting());
    }

    @Test
    public void resetPreservesActiveFontState()
    {
        final ChatFont activeFontBefore =
                service.activeChatFontForTesting();

        final ChatFontProfile activeProfileBefore =
                service.activeFontProfileForTesting();

        assertNotNull(
                activeFontBefore);

        assertNotNull(
                activeProfileBefore);

        service.reset();

        assertSame(
                activeFontBefore,
                service.activeChatFontForTesting());

        assertSame(
                activeProfileBefore,
                service.activeFontProfileForTesting());
    }

    @Test
    public void refreshActiveFontStatePreservesPendingProfileSnapshot()
    {
        final ChatFontProfile plainProfile =
                ChatFontRegistry.get(
                        ChatFont.PLAIN_12);

        final ChatFontProfile barbarianProfile =
                ChatFontRegistry.get(
                        ChatFont.BARBARIAN);

        service.setPendingFontProfileForTesting(
                plainProfile);

        when(config.chatFont())
                .thenReturn(
                        ChatFont.BARBARIAN);

        service.refreshActiveFontState();

        assertSame(
                barbarianProfile,
                service.activeFontProfileForTesting());

        assertSame(
                plainProfile,
                service.pendingFontProfileForTesting());
    }

    /*
     * ================================================================
     * IDEMPOTENT WIDGET MUTATION
     * ================================================================
     */

    @Test
    public void unchangedWidgetDoesNotMutate()
    {
        final Widget widget =
                mock(
                        Widget.class);

        when(widget.getFontId())
                .thenReturn(
                        12);

        final boolean changed =
                service.setFontIdIfChanged(
                        widget,
                        12);

        assertFalse(
                changed);

        verify(
                widget,
                never())
                .setFontId(
                        12);
    }

    @Test
    public void changedWidgetMutatesOnlyOnceAfterStateMatches()
    {
        final Widget widget =
                mock(
                        Widget.class);

        final AtomicInteger currentFontId =
                new AtomicInteger(
                        12);

        when(widget.getFontId())
                .thenAnswer(
                        ignored ->
                                currentFontId.get());

        doAnswer(
                invocation ->
                {
                    currentFontId.set(
                            (Integer) invocation.getArgument(
                                    0));

                    return null;
                })
                .when(
                        widget)
                .setFontId(
                        99);

        assertTrue(
                service.setFontIdIfChanged(
                        widget,
                        99));

        assertFalse(
                service.setFontIdIfChanged(
                        widget,
                        99));

        verify(
                widget,
                times(
                        1))
                .setFontId(
                        99);
    }

    /*
     * ================================================================
     * CONDITIONAL REVALIDATION
     * ================================================================
     */

    @Test
    public void unchangedWidgetDoesNotRevalidate()
    {
        final Widget widget =
                mock(
                        Widget.class);

        service.revalidateWidgetIfChanged(
                widget,
                false);

        verify(
                widget,
                never())
                .revalidate();
    }

    @Test
    public void changedWidgetRevalidatesOnce()
    {
        final Widget widget =
                mock(
                        Widget.class);

        service.revalidateWidgetIfChanged(
                widget,
                true);

        verify(
                widget,
                times(
                        1))
                .revalidate();
    }

    @Test
    public void multipleChangesToSameWidgetRevalidateOnce()
    {
        final Widget widget =
                mock(
                        Widget.class);

        when(widget.getFontId())
                .thenReturn(
                        12);

        when(widget.getOriginalWidth())
                .thenReturn(
                        100);

        boolean changed =
                service.setFontIdIfChanged(
                        widget,
                        99);

        changed |=
                service.setOriginalWidthIfChanged(
                        widget,
                        200);

        service.revalidateWidgetIfChanged(
                widget,
                changed);

        verify(
                widget,
                times(
                        1))
                .setFontId(
                        99);

        verify(
                widget,
                times(
                        1))
                .setOriginalWidth(
                        200);

        verify(
                widget,
                times(
                        1))
                .revalidate();
    }

    /*
     * ================================================================
     * ROW INDEX INTEGRATION
     * ================================================================
     */

    @Test
    @SuppressWarnings("deprecation")
    public void chatXlYOffsetReturningToNativeRowRepairsWithoutFullRebuild()
    {
        final Widget root =
                mock(
                        Widget.class);

        final Widget lineWidget =
                rowWidget(
                        42,
                        84);

        final Widget bodyWidget =
                mutableRowWidget(
                        42,
                        84);

        when(root.getDynamicChildren())
                .thenReturn(
                        new Widget[]
                                {
                                        lineWidget,
                                        bodyWidget
                                });

        when(client.getWidget(
                InterfaceID.Chatbox.SCROLLAREA))
                .thenReturn(
                        root);

        final List<Widget> first =
                service.collectRow(
                        lineWidget,
                        FontLayoutService.Surface.CHATBOX);

        assertTrue(
                first.contains(
                        bodyWidget));

        /*
         * Move the indexed widget away from its original row.
         */
        service.applySynchronizedYOffset(
                bodyWidget,
                5);

        assertEquals(
                47,
                bodyWidget.getOriginalY());

        assertEquals(
                47,
                bodyWidget.getRelativeY());

        /*
         * Restore the widget's original geometry.
         */
        bodyWidget.setOriginalY(
                42);

        bodyWidget.setRelativeY(
                84);

        final List<Widget> second =
                service.collectRow(
                        lineWidget,
                        FontLayoutService.Surface.CHATBOX);

        assertTrue(
                second.contains(
                        bodyWidget));

        /*
         * Repair the watched move locally without rebuilding the surface.
         */
        verify(
                root,
                times(
                        1))
                .getDynamicChildren();
    }

    @Test
    public void resetClearsRowIndexes()
    {
        final Widget root =
                mock(
                        Widget.class);

        final Widget lineWidget =
                rowWidget(
                        42,
                        84);

        when(root.getDynamicChildren())
                .thenReturn(
                        new Widget[]
                                {
                                        lineWidget
                                });

        when(client.getWidget(
                InterfaceID.Chatbox.SCROLLAREA))
                .thenReturn(
                        root);

        service.collectRow(
                lineWidget,
                FontLayoutService.Surface.CHATBOX);

        service.reset();

        service.collectRow(
                lineWidget,
                FontLayoutService.Surface.CHATBOX);

        /*
         * reset() deliberately discards persistent row indexes.
         */
        verify(
                root,
                times(
                        2))
                .getDynamicChildren();
    }

    /*
     * ================================================================
     * HELPERS
     * ================================================================
     */

    private Widget rowWidget(
            int originalY,
            int relativeY)
    {
        final Widget widget =
                mock(
                        Widget.class);

        when(widget.getOriginalY())
                .thenReturn(
                        originalY);

        when(widget.getRelativeY())
                .thenReturn(
                        relativeY);

        return widget;
    }

    @SuppressWarnings("deprecation")
    private Widget mutableRowWidget(
            int originalY,
            int relativeY)
    {
        final Widget widget =
                mock(
                        Widget.class);

        final AtomicInteger currentOriginalY =
                new AtomicInteger(
                        originalY);

        final AtomicInteger currentRelativeY =
                new AtomicInteger(
                        relativeY);

        when(widget.getOriginalY())
                .thenAnswer(
                        ignored ->
                                currentOriginalY.get());

        when(widget.getRelativeY())
                .thenAnswer(
                        ignored ->
                                currentRelativeY.get());

        doAnswer(
                invocation ->
                {
                    currentOriginalY.set(
                            (Integer) invocation.getArgument(
                                    0));

                    return null;
                })
                .when(
                        widget)
                .setOriginalY(
                        org.mockito.ArgumentMatchers.anyInt());

        doAnswer(
                invocation ->
                {
                    currentRelativeY.set(
                            (Integer) invocation.getArgument(
                                    0));

                    return null;
                })
                .when(
                        widget)
                .setRelativeY(
                        org.mockito.ArgumentMatchers.anyInt());

        return widget;
    }
}

package com.bigboldchat.chat;

import com.bigboldchat.debug.PerformanceMetrics;

import java.util.List;
import java.util.concurrent.atomic.AtomicInteger;

import net.runelite.api.Client;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.Widget;

import org.junit.Before;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.times;
import static org.mockito.Mockito.verify;
import static org.mockito.Mockito.when;

/**
 * Characterization tests for persistent shallow row indexing.
 *
 * These tests protect:
 *
 *  - first-build behavior;
 *  - direct row reuse;
 *  - local geometry repair;
 *  - conservative rebuild on an unknown row anchor;
 *  - index enrichment from a known surface scan.
 */
public class RowCorrelationIndexTest
{
    private Client client;

    private PerformanceMetrics performanceMetrics;

    @Before
    public void setUp()
    {
        client =
                mock(
                        Client.class);

        performanceMetrics =
                new PerformanceMetrics();
    }

    /*
     * ================================================================
     * TESTS
     * ================================================================
     */

    @Test
    public void firstRowLookupBuildsIndex()
    {
        final Widget root =
                mock(
                        Widget.class);

        final Widget lineWidget =
                rowWidget(
                        42,
                        84);

        final Widget bodyWidget =
                rowWidget(
                        42,
                        84);

        when(root.getDynamicChildren())
                .thenReturn(
                        new Widget[]
                                {
                                        lineWidget,
                                        bodyWidget
                                });

        when(client.getWidget(
                InterfaceID.Chatbox.SCROLLAREA))
                .thenReturn(
                        root);

        final RowCorrelationIndex rowIndex =
                rowIndex();

        final List<Widget> row =
                rowIndex.findRow(
                        lineWidget);

        assertEquals(
                2,
                row.size());

        assertTrue(
                row.contains(
                        lineWidget));

        assertTrue(
                row.contains(
                        bodyWidget));

        verify(
                root,
                times(
                        1))
                .getDynamicChildren();
    }

    @Test
    public void laterRowLookupReusesIndex()
    {
        final Widget root =
                mock(
                        Widget.class);

        final Widget lineWidget =
                rowWidget(
                        42,
                        84);

        final Widget bodyWidget =
                rowWidget(
                        42,
                        84);

        when(root.getDynamicChildren())
                .thenReturn(
                        new Widget[]
                                {
                                        lineWidget,
                                        bodyWidget
                                });

        when(client.getWidget(
                InterfaceID.Chatbox.SCROLLAREA))
                .thenReturn(
                        root);

        final RowCorrelationIndex rowIndex =
                rowIndex();

        final List<Widget> first =
                rowIndex.findRow(
                        lineWidget);

        final List<Widget> second =
                rowIndex.findRow(
                        lineWidget);

        assertEquals(
                first,
                second);

        /*
         * Direct reuse must not enumerate the surface again.
         */
        verify(
                root,
                times(
                        1))
                .getDynamicChildren();

        verify(
                root,
                times(
                        1))
                .getStaticChildren();

        verify(
                root,
                times(
                        1))
                .getNestedChildren();
    }

    @Test
    public void movedCachedWidgetRepairsIndexWithoutFullRebuild()
    {
        final Widget root =
                mock(
                        Widget.class);

        final Widget lineWidget =
                rowWidget(
                        42,
                        84);

        final Widget bodyWidget =
                mock(
                        Widget.class);

        final AtomicInteger bodyOriginalY =
                new AtomicInteger(
                        42);

        when(bodyWidget.getOriginalY())
                .thenAnswer(
                        ignored ->
                                bodyOriginalY.get());

        when(bodyWidget.getRelativeY())
                .thenReturn(
                        84);

        when(root.getDynamicChildren())
                .thenReturn(
                        new Widget[]
                                {
                                        lineWidget,
                                        bodyWidget
                                });

        when(client.getWidget(
                InterfaceID.Chatbox.SCROLLAREA))
                .thenReturn(
                        root);

        final RowCorrelationIndex rowIndex =
                rowIndex();

        final List<Widget> first =
                rowIndex.findRow(
                        lineWidget);

        assertTrue(
                first.contains(
                        bodyWidget));

        bodyOriginalY.set(
                43);

        final List<Widget> second =
                rowIndex.findRow(
                        lineWidget);

        assertFalse(
                second.contains(
                        bodyWidget));

        /*
         * Local repair must not rebuild the surface.
         */
        verify(
                root,
                times(
                        1))
                .getDynamicChildren();
    }

    @Test
    public void missingRowRefreshesIndexOnce()
    {
        final Widget root =
                mock(
                        Widget.class);

        final Widget existingLine =
                rowWidget(
                        42,
                        84);

        final Widget requestedMissingLine =
                rowWidget(
                        100,
                        200);

        when(root.getDynamicChildren())
                .thenReturn(
                        new Widget[]
                                {
                                        existingLine
                                });

        when(client.getWidget(
                InterfaceID.Chatbox.SCROLLAREA))
                .thenReturn(
                        root);

        final RowCorrelationIndex rowIndex =
                rowIndex();

        rowIndex.findRow(
                existingLine);

        final List<Widget> missing =
                rowIndex.findRow(
                        requestedMissingLine);

        assertTrue(
                missing.isEmpty());

        /*
         * An unknown row anchor is confirmed with one rebuild.
         */
        verify(
                root,
                times(
                        2))
                .getDynamicChildren();
    }

    @Test
    public void observedSurfaceWidgetEnrichesIndexWithoutRebuild()
    {
        final Widget root =
                mock(
                        Widget.class);

        final Widget lineWidget =
                rowWidget(
                        42,
                        84);

        final Widget observedWidget =
                rowWidget(
                        42,
                        84);

        when(root.getDynamicChildren())
                .thenReturn(
                        new Widget[]
                                {
                                        lineWidget
                                });

        when(client.getWidget(
                InterfaceID.Chatbox.SCROLLAREA))
                .thenReturn(
                        root);

        final RowCorrelationIndex rowIndex =
                rowIndex();

        final List<Widget> first =
                rowIndex.findRow(
                        lineWidget);

        assertEquals(
                1,
                first.size());

        rowIndex.observeSurfaceWidget(
                root,
                observedWidget);

        final List<Widget> second =
                rowIndex.findRow(
                        lineWidget);

        assertEquals(
                2,
                second.size());

        assertTrue(
                second.contains(
                        lineWidget));

        assertTrue(
                second.contains(
                        observedWidget));

        /*
         * Enrichment must reuse the existing surface index.
         */
        verify(
                root,
                times(
                        1))
                .getDynamicChildren();

        verify(
                root,
                times(
                        1))
                .getStaticChildren();

        verify(
                root,
                times(
                        1))
                .getNestedChildren();
    }

    private RowCorrelationIndex rowIndex()
    {
        return new RowCorrelationIndex(
                client,
                FontLayoutService.Surface.CHATBOX,
                performanceMetrics);
    }

    private Widget rowWidget(
            int originalY,
            int relativeY)
    {
        final Widget widget =
                mock(
                        Widget.class);

        when(widget.getOriginalY())
                .thenReturn(
                        originalY);

        when(widget.getRelativeY())
                .thenReturn(
                        relativeY);

        return widget;
    }
}

package com.bigboldchat.chat;

import org.junit.Before;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

public class ChatTextNormalizerTest
{
    private static final boolean PERFORMANCE_TEST = false;
    private static final int PERFORMANCE_WARMUP_ITERATIONS = 10_000;
    private static final int PERFORMANCE_ITERATIONS = 100_000;

    private ChatTextNormalizer normalizer;

    @Before
    public void setUp()
    {
        normalizer =
                new ChatTextNormalizer();
    }

    /*
     * TESTS
     */

    @Test
    public void normalizeSemanticPreservesCurrentNullAndTrimBehavior()
    {
        assertNull(
                normalizer.normalizeSemantic(
                        null));

        assertEquals(
                "hello",
                normalizer.normalizeSemantic(
                        " hello "));
    }

    @Test
    public void normalizeSemanticRemovesRuneScapeMarkup()
    {
        assertEquals(
                "Hello",
                normalizer.normalizeSemantic(
                        "<col=ff0000>Hello</col>"));
    }

    @Test
    public void normalizeSemanticConvertsNonBreakingSpaces()
    {
        assertEquals(
                "Hello world",
                normalizer.normalizeSemantic(
                        "Hello\u00A0world"));
    }

    @Test
    public void normalizeSemanticPreservesExplicitLineBreaks()
    {
        assertEquals(
                "one\ntwo",
                normalizer.normalizeSemantic(
                        "one<br>two"));

        assertEquals(
                "one\ntwo",
                normalizer.normalizeSemantic(
                        "one<BR>two"));

        assertEquals(
                "one\ntwo",
                normalizer.normalizeSemantic(
                        "one<br/>two"));

        assertEquals(
                "one\ntwo",
                normalizer.normalizeSemantic(
                        "one<br />two"));

        assertEquals(
                "one\ntwo",
                normalizer.normalizeSemantic(
                        "one<Br   />two"));
    }

    @Test
    public void normalizeSemanticConvertsAtEscapeToVisibleCharacter()
    {
        assertEquals(
                "@",
                normalizer.normalizeSemantic(
                        "<at>"));

        assertEquals(
                "@",
                normalizer.normalizeSemantic(
                        "<AT>"));
    }

    @Test
    public void normalizeSemanticPreservesAtOnlyMessages()
    {
        assertEquals(
                "@@@@@@@@@@@@@@",
                normalizer.normalizeSemantic(
                        "<at><at><at><at><at><at><at>"
                                + "<at><at><at><at><at><at><at>"));
    }

    @Test
    public void normalizeSemanticConvertsLeadingAtEscapeWithText()
    {
        assertEquals(
                "@player",
                normalizer.normalizeSemantic(
                        "<at>player"));

        assertEquals(
                "@Player_Name",
                normalizer.normalizeSemantic(
                        "<at>Player_Name"));
    }

    @Test
    public void normalizeSemanticConvertsInlineAtEscapeWithText()
    {
        assertEquals(
                "Hello @player",
                normalizer.normalizeSemantic(
                        "Hello <at>player"));

        assertEquals(
                "Congrats @cr_zy92 !!!~~~~",
                normalizer.normalizeSemantic(
                        "Congrats <at>cr_zy92 !!!~~~~"));
    }

    @Test
    public void measureSemanticConvertsAtEscapeToVisibleCharacter()
    {
        assertEquals(
                "@",
                normalizer.measureSemantic(
                        "<at>"));

        assertEquals(
                "@player",
                normalizer.measureSemantic(
                        "<at>player"));

        assertEquals(
                "@@@",
                normalizer.measureSemantic(
                        "<at><at><at>"));

        assertEquals(
                "<col=ffffff>Hello @player</col>",
                normalizer.measureSemantic(
                        "<col=ffffff>Hello <at>player</col>"));
    }

    @Test
    public void measureSemanticPreservesInlineImages()
    {
        assertEquals(
                "<col=00ea8b>Hello <img=412> world</col>",
                normalizer.measureSemantic(
                        "<col=00ea8b>Hello\u00A0<img=412>\u00A0world</col>"));
    }

    @Test
    public void measureSemanticPreservesExplicitLineBreaks()
    {
        assertEquals(
                "<col=00ea8b>one\ntwo <img=412></col>",
                normalizer.measureSemantic(
                        "<col=00ea8b>one<br>two <img=412></col>"));

        assertEquals(
                "<col=00ea8b>one\ntwo <img=412></col>",
                normalizer.measureSemantic(
                        "<col=00ea8b>one<BR />two <img=412></col>"));
    }

    @Test
    public void measureSemanticPreservesNullAndTrimBehavior()
    {
        assertNull(
                normalizer.measureSemantic(
                        null));

        assertEquals(
                "",
                normalizer.measureSemantic(
                        "   "));

        assertEquals(
                "Hello world",
                normalizer.measureSemantic(
                        "  Hello world  "));
    }

    @Test
    public void normalizeSemanticPreservesImageOnlyMessages()
    {
        assertEquals(
                "<img=413>",
                normalizer.normalizeSemantic(
                        "<col=9090ff><img=413></col>"));

        assertEquals(
                "<img=412><img=413>",
                normalizer.normalizeSemantic(
                        "<col=9090ff><img=412><img=413></col>"));

        assertEquals(
                "<img=413>",
                normalizer.normalizeSemantic(
                        "<col=9090ff><IMG=413></col>"));
    }

    @Test
    public void normalizeSemanticRemovesInlineImagesFromText()
    {
        assertEquals(
                "Hello  world",
                normalizer.normalizeSemantic(
                        "<col=9090ff>Hello <img=413> world</col>"));
    }

    /*
     * PERFORMANCE
     */

    @Test
    public void performanceNormalizeSemantic()
    {
        if (!PERFORMANCE_TEST)
        {
            return;
        }

        final String plainText =
                "Hello everyone this is a normal RuneScape chat message";

        final String markupText =
                "<col=ff0000>Hello\u00A0everyone</col>"
                        + "<br />"
                        + "<u>PlayerName:</u>";

        long checksum =
                0L;

        for (int i = 0;
             i < PERFORMANCE_WARMUP_ITERATIONS;
             i++)
        {
            checksum +=
                    normalizer.normalizeSemantic(
                                    plainText)
                            .length();

            checksum +=
                    normalizer.normalizeSemantic(
                                    markupText)
                            .length();
        }

        long started =
                System.nanoTime();

        for (int i = 0;
             i < PERFORMANCE_ITERATIONS;
             i++)
        {
            checksum +=
                    normalizer.normalizeSemantic(
                                    plainText)
                            .length();
        }

        final long plainElapsed =
                System.nanoTime()
                        - started;

        started =
                System.nanoTime();

        for (int i = 0;
             i < PERFORMANCE_ITERATIONS;
             i++)
        {
            checksum +=
                    normalizer.normalizeSemantic(
                                    markupText)
                            .length();
        }

        final long markupElapsed =
                System.nanoTime()
                        - started;

        assertTrue(
                checksum > 0L);

        final double plainTotalMs =
                plainElapsed
                        / 1_000_000.0;

        final double markupTotalMs =
                markupElapsed
                        / 1_000_000.0;

        System.out.printf(
                "[Chat XL][ChatTextNormalizerTest] Performance= "
                        + "NormalizePlain: %.3fms (%.6fms) | "
                        + "NormalizeMarkup: %.3fms (%.6fms) | "
                        + "Iterations: %d%n",
                plainTotalMs,
                plainTotalMs
                        / PERFORMANCE_ITERATIONS,
                markupTotalMs,
                markupTotalMs
                        / PERFORMANCE_ITERATIONS,
                PERFORMANCE_ITERATIONS);
    }
}

package com.bigboldchat.config;

import net.runelite.api.FontID;
import org.junit.Test;

import static org.junit.Assert.assertArrayEquals;
import static org.junit.Assert.assertEquals;

/**
 * Locks down Chat XL's player-facing font names and RuneScape FontID mappings.
 *
 * These names are part of the plugin's public configuration contract and should
 * not change as a side effect of internal performance refactors.
 */
public class ChatFontTest
{

    /*
     * TESTS
     */

    @Test
    public void exposesExpectedFontsInExpectedOrder()
    {
        assertArrayEquals(
                new ChatFont[]
                {
                        ChatFont.PLAIN_11,
                        ChatFont.PLAIN_12,
                        ChatFont.BOLD_12,
                        ChatFont.QUILL_8,
                        ChatFont.QUILL_MEDIUM,
                        ChatFont.BARBARIAN,
                        ChatFont.TAHOMA_11,
                        ChatFont.VERDANA_11,
                        ChatFont.VERDANA_11_BOLD,
                        ChatFont.VERDANA_13,
                        ChatFont.VERDANA_13_BOLD,
                        ChatFont.VERDANA_15
                },
                ChatFont.values());
    }

    @Test
    public void preservesPlayerFacingNamesAndFontIds()
    {
        assertFont(ChatFont.PLAIN_11, "Plain 11", FontID.PLAIN_11);
        assertFont(ChatFont.PLAIN_12, "Plain 12 (Default)", FontID.PLAIN_12);
        assertFont(ChatFont.BOLD_12, "Bold 12", FontID.BOLD_12);

        assertFont(ChatFont.QUILL_8, "Quill Small", FontID.QUILL_8);
        assertFont(ChatFont.QUILL_MEDIUM, "Quill Medium", FontID.QUILL_MEDIUM);
        assertFont(ChatFont.BARBARIAN, "Barbarian", FontID.BARBARIAN);

        assertFont(ChatFont.TAHOMA_11, "Tahoma 11", FontID.TAHOMA_11);
        assertFont(ChatFont.VERDANA_11, "Verdana 11", FontID.VERDANA_11);
        assertFont(ChatFont.VERDANA_11_BOLD, "Verdana 11 Bold", FontID.VERDANA_11_BOLD);
        assertFont(ChatFont.VERDANA_13, "Verdana 13", FontID.VERDANA_13);
        assertFont(ChatFont.VERDANA_13_BOLD, "Verdana 13 Bold", FontID.VERDANA_13_BOLD);
        assertFont(ChatFont.VERDANA_15, "Verdana 15", FontID.VERDANA_15);
    }

    /*
     * HELPERS
     */

    private static void assertFont(
            ChatFont font,
            String expectedDisplayName,
            int expectedFontId)
    {
        assertEquals(expectedDisplayName, font.toString());
        assertEquals(expectedFontId, font.getFontId());
    }
}

