        final NativeWidgetState state =
                nativeState(
                        widget);

        final int currentLineHeight =
                widget.getLineHeight();

        if (!state.lineHeightCaptured
                || currentLineHeight
                != state.appliedLineHeight)
        {
            state.nativeLineHeight =
                    currentLineHeight;

            state.lineHeightCaptured =
                    true;
        }

        state.appliedLineHeight =
                lineHeight;

        widget.setLineHeight(
                lineHeight);

        recordWidgetMutation();
        return true;
    }

    private boolean setTextIfChanged(
            Widget widget,
            String text)
    {
        if (widget == null
                || text == null
                || text.equals(
                widget.getText()))
        {
            return false;
        }

        final NativeWidgetState state =
                nativeState(
                        widget);

        final String currentText =
                widget.getText();

        if (!state.textCaptured
                || !sameText(
                currentText,
                state.appliedText))
        {
            state.nativeText =
                    currentText;

            state.textCaptured =
                    true;
        }

        state.appliedText =
                text;

        widget.setText(
                text);

        recordWidgetMutation();
        return true;
    }

