    private NativeWidgetState nativeState(
            Widget widget)
    {
        return nativeWidgetStates.computeIfAbsent(
                widget,
                ignored -> new NativeWidgetState());
    }

    private boolean sameText(
            String left,
            String right)
    {
        return left == null
                ? right == null
                : left.equals(
                right);
    }

    private void recordWidgetMutation()
    {
        if (performanceMetrics != null)
        {
            performanceMetrics.recordWidgetMutation();
        }
    }

    void revalidateWidgetIfChanged(
            Widget widget,
            boolean changed)
    {
        if (widget == null
                || !changed)
        {
            return;
        }

        widget.revalidate();

        if (performanceMetrics != null)
        {
            performanceMetrics.recordRevalidate();
        }
    }

    /*
     * ================================================================
     * ROW CORRELATION
     * ================================================================
     */

    List<Widget> collectRow(
            Widget lineWidget,
            Surface surface)
    {
        if (lineWidget == null
                || surface == null)
        {
            return Collections.emptyList();
        }

        final RowCorrelationIndex rowIndex =
                rowIndexes.computeIfAbsent(
                        surface,
                        key -> new RowCorrelationIndex(
                                client,
                                key,
                                performanceMetrics));

        final List<Widget> result =
                rowIndex.findRow(
                        lineWidget);

        if (performanceMetrics != null)
        {
            performanceMetrics.recordRowSearches(
                    result.size());
        }

        return result;
    }

    private void observeWidgetFromSurfaceScan(
            Surface surface,
            Widget root,
            Widget widget)
    {
        if (surface == null
                || root == null
                || widget == null)
        {
            return;
        }

        final RowCorrelationIndex rowIndex =
                rowIndexes.get(
                        surface);

        if (rowIndex != null)
        {
            rowIndex.observeSurfaceWidget(
                    root,
                    widget);
        }
    }

    private void notifyIndexedWidgetGeometryChanged(
            Widget widget,
            int previousOriginalY,
            int previousRelativeY)
    {
        if (widget == null
                || rowIndexes.isEmpty())
        {
            return;
        }

        for (RowCorrelationIndex rowIndex : rowIndexes.values())
        {
            if (rowIndex != null)
            {
                rowIndex.onWidgetGeometryChangedByChatXl(
                        widget,
                        previousOriginalY,
                        previousRelativeY);
            }
        }
    }

    private boolean containsIdentity(
            List<Widget> widgets,
            Widget target)
    {
        if (widgets == null
                || target == null)
        {
            return false;
        }

        for (Widget widget : widgets)
        {
            if (widget == target)
            {
                return true;
            }
        }

        return false;
    }

    private void removeIdentity(
            List<Widget> widgets,
            Widget target)
    {
        if (widgets == null
                || target == null)
        {
            return;
        }

        for (int i = widgets.size() - 1;
             i >= 0;
             i--)
        {
            if (widgets.get(
                    i) == target)
            {
                widgets.remove(
                        i);
            }
        }
    }

    private Widget matchRow(
            List<Widget> rowWidgets,
            String targetText,
            Widget excludedWidget)
    {
        if (rowWidgets == null
                || rowWidgets.isEmpty()
                || targetText == null)
        {
            return null;
        }

        Widget match =
                null;

        int matches =
                0;

        for (Widget widget : rowWidgets)
        {
            if (widget == null
                    || widget == excludedWidget)
            {
                continue;
            }

            final String semantic =
                    textNormalizer.normalizeSemantic(
                            widget.getText());

            if (semantic == null
                    || !semantic.equalsIgnoreCase(
                    targetText))
            {
                continue;
            }

            match =
                    widget;

            matches++;

            if (matches > 1)
            {
                return null;
            }
        }

        return matches == 1
                ? match
                : null;
    }

    /*
     * ================================================================
     * BODY CORRELATION
     * ================================================================
     */

    Widget findTargetWidgetForLine(
            String targetText,
            Widget lineWidget,
            Surface surface,
            List<Widget> rowWidgets,
            FallbackCorrelationContext fallbackContext)
    {
        if (targetText == null
                || lineWidget == null
                || surface == null
                || fallbackContext == null)
        {
            return null;
        }

        final Widget rowMatch =
                matchRow(
                        rowWidgets,
                        targetText,
                        null);

        if (rowMatch != null)
        {
            return rowMatch;
        }

        final List<Widget> matches =
                fallbackContext.findMatches(
                        targetText);

        if (matches.isEmpty())
        {
            return null;
        }

        /*
         * Strongest match:
         *
         * same OriginalY + same RelativeY.
         */
        for (Widget widget : matches)
        {
            if (widget.getOriginalY()
                    == lineWidget.getOriginalY()
                    && widget.getRelativeY()
                    == lineWidget.getRelativeY())
            {
                return widget;
            }
        }

        /*
         * Next strongest:
         *
         * unique OriginalY.
         */
        Widget originalYMatch =
                null;

        int originalYMatches =
                0;

        for (Widget widget : matches)
        {
            if (widget.getOriginalY()
                    == lineWidget.getOriginalY())
            {
                originalYMatch =
                        widget;

                originalYMatches++;
            }
        }

        if (originalYMatches == 1)
        {
            return originalYMatch;
        }

        /*
         * Next:
         *
         * unique RelativeY.
         */
        Widget relativeYMatch =
                null;

        int relativeYMatches =
                0;

        for (Widget widget : matches)
        {
            if (widget.getRelativeY()
                    == lineWidget.getRelativeY())
            {
                relativeYMatch =
                        widget;

                relativeYMatches++;
            }
        }

        if (relativeYMatches == 1)
        {
            return relativeYMatch;
        }

        /*
         * Final conservative fallback:
         *
         * exactly one semantic match on the entire surface.
         */
        return matches.size() == 1
                ? matches.get(0)
                : null;
    }

    /*
     * ================================================================
     * PREFIX CORRELATION
     * ================================================================
     */

    private List<Widget> findPrefixWidgetsForLine(
            List<String> rawPrefixComponents,
            Widget lineWidget,
            Surface surface,
            Widget bodyWidget,
            List<Widget> rowWidgets,
            FallbackCorrelationContext fallbackContext)
    {
        if (rawPrefixComponents == null
                || rawPrefixComponents.isEmpty()
                || lineWidget == null
                || surface == null
                || bodyWidget == null
                || fallbackContext == null)
        {
            return Collections.emptyList();
        }

        final List<Widget> result =
                new ArrayList<>();

        for (String rawPrefix : rawPrefixComponents)
        {
            final String targetText =
                    textNormalizer.normalizeSemantic(
                            rawPrefix);

            if (targetText == null
                    || targetText.isEmpty())
            {
                continue;
            }

            final Widget rowMatch =
                    matchRow(
                            rowWidgets,
                            targetText,
                            bodyWidget);

            if (rowMatch != null
                    && !containsIdentity(
                    result,
                    rowMatch))
            {
                result.add(
                        rowMatch);

                continue;
            }

            final List<Widget> matches =
                    fallbackContext.findMatches(
                            targetText);

            if (matches.isEmpty())
            {
                continue;
            }

            Widget selected =
                    null;

            /*
             * Prefer the exact body row.
             */
            for (Widget candidate : matches)
            {
                if (candidate == bodyWidget
                        || containsIdentity(
                        result,
                        candidate))
                {
                    continue;
                }

                if (candidate.getOriginalY()
                        == bodyWidget.getOriginalY()
                        && candidate.getRelativeY()
                        == bodyWidget.getRelativeY())
                {
                    if (selected != null)
                    {
                        selected =
                                null;
                        break;
                    }

                    selected =
                            candidate;
                }
            }

            if (selected == null)
            {
                /*
                 * Then prefer a unique OriginalY match.
                 */
                int originalYMatches =
                        0;

                for (Widget candidate : matches)
                {
                    if (candidate == bodyWidget
                            || containsIdentity(
                            result,
                            candidate))
                    {
                        continue;
                    }

                    if (candidate.getOriginalY()
                            == bodyWidget.getOriginalY())
                    {
                        selected =
                                candidate;

                        originalYMatches++;
                    }
                }

                if (originalYMatches != 1)
                {
                    selected =
                            null;
                }
            }

            if (selected == null)
            {
                /*
                 * Then prefer a unique RelativeY match.
                 */
                int relativeYMatches =
                        0;

                for (Widget candidate : matches)
                {
                    if (candidate == bodyWidget
                            || containsIdentity(
                            result,
                            candidate))
                    {
                        continue;
                    }

                    if (candidate.getRelativeY()
                            == bodyWidget.getRelativeY())
                    {
                        selected =
                                candidate;

                        relativeYMatches++;
                    }
                }

                if (relativeYMatches != 1)
                {
                    selected =
                            null;
                }
            }

            if (selected == null)
            {
                /*
                 * Final conservative fallback:
                 *
                 * exactly one remaining semantic match.
                 */
                Widget onlyRemaining =
                        null;

                int remaining =
                        0;

                for (Widget candidate : matches)
                {
                    if (candidate == bodyWidget
                            || containsIdentity(
                            result,
                            candidate))
                    {
                        continue;
                    }

                    onlyRemaining =
                            candidate;

                    remaining++;
                }

                if (remaining == 1)
                {
                    selected =
                            onlyRemaining;
                }
            }

            if (selected != null
                    && !containsIdentity(
                    result,
                    selected))
            {
                result.add(
                        selected);
            }
        }

        return result;
    }

    /*
     * ================================================================
     * RANK ICON CORRELATION
     * ================================================================
     */

    Widget findRankIconWidget(
            FontMeasurementService.ChannelPrefixLayout nativeLayout,
            Widget rowAnchor,
            List<Widget> rowWidgets)
    {
        if (nativeLayout == null
                || rowAnchor == null
                || nativeLayout.rankIconSpriteId < 0)
        {
            return null;
        }

        if (performanceMetrics != null)
        {
            performanceMetrics.recordRankSearch();
        }

        /*
         * First inspect the already-collected row.
         *
         * This remains the common path. The diagnostic counters below classify
         * why this strict row-first lookup failed without changing its matching
         * criteria.
         */
        final Widget rowMatch =
                findRankIconWidgetInRow(
                        nativeLayout,
                        rowAnchor,
                        rowWidgets);

        if (rowMatch != null)
        {
            return rowMatch;
        }

        final Widget root =
                client.getWidget(
                        InterfaceID.Chatbox.SCROLLAREA);

        if (root == null)
        {
            if (performanceMetrics != null)
            {
                performanceMetrics.recordRankFallback();
                performanceMetrics.recordRankFallbackMiss();
            }

            return null;
        }

        /*
         * Retry a missed rank lookup across the row index's shallow scan domain:
         * root plus immediate dynamic/static/nested children.
         */
        final Widget shallowMatch =
                findRankIconWidgetShallow(
                        root,
                        nativeLayout.rankIconSpriteId,
                        nativeLayout.rankIconX,
                        rowAnchor.getOriginalY(),
                        rowAnchor.getRelativeY());

        if (shallowMatch != null)
        {
            if (performanceMetrics != null)
            {
                performanceMetrics.recordRankShallowRecovery();
            }

            observeWidgetFromSurfaceScan(
                    Surface.CHATBOX,
                    root,
                    shallowMatch);

            return shallowMatch;
        }

        /*
         * Preserve the recursive tree search as the final correctness fallback.
         * RankFallback therefore continues to mean that the full-tree path was
         * actually required.
         */
        if (performanceMetrics != null)
        {
            performanceMetrics.recordRankFallback();
        }

        final Widget fallbackMatch =
                findRankIconWidgetRecursive(
                        root,
                        nativeLayout.rankIconSpriteId,
                        nativeLayout.rankIconX,
                        rowAnchor.getOriginalY(),
                        rowAnchor.getRelativeY());

        if (performanceMetrics != null)
        {
            if (fallbackMatch != null)
            {
                performanceMetrics.recordRankFallbackHit();
            }
            else
            {
                performanceMetrics.recordRankFallbackMiss();
            }
        }

        /*
         * Add a recursively found rank widget to the persistent row index.
         */
        if (fallbackMatch != null)
        {
            observeWidgetFromSurfaceScan(
                    Surface.CHATBOX,
                    root,
                    fallbackMatch);
        }

        return fallbackMatch;
    }

    private Widget findRankIconWidgetInRow(
            FontMeasurementService.ChannelPrefixLayout nativeLayout,
            Widget rowAnchor,
            List<Widget> rowWidgets)
    {
        boolean spriteMatched =
                false;

        boolean xMatched =
                false;

        if (rowWidgets == null
                || rowWidgets.isEmpty())
        {
            if (performanceMetrics != null)
            {
                performanceMetrics.recordRankRowNoSprite();
            }

            return null;
        }

        for (Widget widget : rowWidgets)
        {
            if (widget == null)
            {
                continue;
            }

            if (performanceMetrics != null)
            {
                performanceMetrics.recordRankNodesExamined(
                        1);
            }

            if (widget.getSpriteId()
                    != nativeLayout.rankIconSpriteId)
            {
                continue;
            }

            spriteMatched =
                    true;

            if (widget.getOriginalX()
                    != nativeLayout.rankIconX)
            {
                continue;
            }

            xMatched =
                    true;

            if (widget.getOriginalY()
                    != rowAnchor.getOriginalY()
                    && widget.getRelativeY()
                    != rowAnchor.getRelativeY())
            {
                continue;
            }

            return widget;
        }

        if (performanceMetrics != null)
        {
            if (!spriteMatched)
            {
                performanceMetrics.recordRankRowNoSprite();
            }
            else if (!xMatched)
            {
                performanceMetrics.recordRankRowXMismatch();
            }
            else
            {
                performanceMetrics.recordRankRowYMismatch();
            }
        }

        return null;
    }

    private Widget findRankIconWidgetShallow(
            Widget root,
            int spriteId,
            int originalX,
            int originalY,
            int relativeY)
    {
        if (root == null)
        {
            return null;
        }

        Widget match =
                findRankIconWidgetCandidate(
                        root,
                        spriteId,
                        originalX,
                        originalY,
                        relativeY);

        if (match != null)
        {
            return match;
        }

        match =
                findRankIconWidgetInShallowArray(
                        root.getDynamicChildren(),
                        spriteId,
                        originalX,
                        originalY,
                        relativeY);

        if (match != null)
        {
            return match;
        }

        match =
                findRankIconWidgetInShallowArray(
                        root.getStaticChildren(),
                        spriteId,
                        originalX,
                        originalY,
                        relativeY);

        if (match != null)
        {
            return match;
        }

        return findRankIconWidgetInShallowArray(
                root.getNestedChildren(),
                spriteId,
                originalX,
                originalY,
                relativeY);
    }

    private Widget findRankIconWidgetInShallowArray(
            Widget[] widgets,
            int spriteId,
            int originalX,
            int originalY,
            int relativeY)
    {
        if (widgets == null)
        {
            return null;
        }

        for (Widget widget : widgets)
        {
            final Widget match =
                    findRankIconWidgetCandidate(
                            widget,
                            spriteId,
                            originalX,
                            originalY,
                            relativeY);

            if (match != null)
            {
                return match;
            }
        }

        return null;
    }

    private Widget findRankIconWidgetCandidate(
            Widget widget,
            int spriteId,
            int originalX,
            int originalY,
            int relativeY)
    {
        if (widget == null)
        {
            return null;
        }

        if (performanceMetrics != null)
        {
            performanceMetrics.recordRankNodesExamined(
                    1);
        }

        return widget.getSpriteId()
                == spriteId
                && widget.getOriginalX()
                == originalX
                && (widget.getOriginalY()
                == originalY
                || widget.getRelativeY()
                == relativeY)
                ? widget
                : null;
    }

    private Widget findRankIconWidgetRecursive(
            Widget widget,
            int spriteId,
            int originalX,
            int originalY,
            int relativeY)
    {
        if (widget == null)
        {
            return null;
        }

        if (performanceMetrics != null)
        {
            performanceMetrics.recordRankNodesExamined(1);
        }

        if (widget.getSpriteId()
                == spriteId
                && widget.getOriginalX()
                == originalX
                && (widget.getOriginalY()
                == originalY
                || widget.getRelativeY()
                == relativeY))
        {
            return widget;
        }

        final Widget[] dynamicChildren =
                widget.getDynamicChildren();

        if (dynamicChildren != null)
        {
            for (Widget child : dynamicChildren)
            {
                final Widget result =
                        findRankIconWidgetRecursive(
                                child,
                                spriteId,
                                originalX,
                                originalY,
                                relativeY);

                if (result != null)
                {
                    return result;
                }
            }
        }

        final Widget[] staticChildren =
                widget.getStaticChildren();

        if (staticChildren != null)
        {
            for (Widget child : staticChildren)
            {
                final Widget result =
                        findRankIconWidgetRecursive(
                                child,
                                spriteId,
                                originalX,
                                originalY,
                                relativeY);

                if (result != null)
                {
                    return result;
                }
            }
        }

        final Widget[] nestedChildren =
                widget.getNestedChildren();

        if (nestedChildren != null)
        {
            for (Widget child : nestedChildren)
            {
                final Widget result =
                        findRankIconWidgetRecursive(
                                child,
                                spriteId,
                                originalX,
                                originalY,
                                relativeY);

                if (result != null)
                {
                    return result;
                }
            }
        }

        return null;
    }

    /*
     * ================================================================
     * FALLBACK CORRELATION
     * ================================================================
     */

    final class FallbackCorrelationContext
    {
        private final Surface surface;

        private Map<String, List<Widget>> widgetsBySemantic;

        FallbackCorrelationContext(
                Surface surface)
        {
            this.surface =
                    surface;
        }

        List<Widget> findMatches(
                String targetText)
        {
            if (targetText == null
                    || targetText.isEmpty()
                    || surface == null)
            {
                return Collections.emptyList();
            }

            if (performanceMetrics != null)
            {
                performanceMetrics.recordFallbackSearch();
            }

            if (widgetsBySemantic == null)
            {
                buildIndex();

                if (performanceMetrics != null)
                {
                    performanceMetrics.recordFallbackBuild();
                }
            }
            else if (performanceMetrics != null)
            {
                performanceMetrics.recordFallbackReuse();
            }

            final List<Widget> matches =
                    widgetsBySemantic.get(
                            semanticKey(
                                    targetText));

            return matches != null
                    ? matches
                    : Collections.emptyList();
        }

        private void buildIndex()
        {
            widgetsBySemantic =
                    new HashMap<>();

            final Widget root =
                    surface == Surface.SPLIT_PRIVATE
                            ? client.getWidget(
                            InterfaceID.PM_CHAT,
                            0)
                            : client.getWidget(
                            InterfaceID.Chatbox.SCROLLAREA);

            if (root == null)
            {
                return;
            }

            if (performanceMetrics != null)
            {
                performanceMetrics.recordSurfaceSearch();
            }

            indexWidget(
                    root,
                    root);

            indexWidgets(
                    root,
                    root.getDynamicChildren());

            indexWidgets(
                    root,
                    root.getStaticChildren());

            indexWidgets(
                    root,
                    root.getNestedChildren());
        }

        private void indexWidgets(
                Widget root,
                Widget[] widgets)
        {
            if (widgets == null)
            {
                return;
            }

            for (Widget widget : widgets)
            {
                indexWidget(
                        root,
                        widget);
            }
        }

        private void indexWidget(
                Widget root,
                Widget widget)
        {
            if (widget == null)
            {
                return;
            }

            if (performanceMetrics != null)
            {
                performanceMetrics.recordWidgetsExamined(
                        1);
            }

            /*
             * A complete fallback scan has already paid the enumeration cost.
             * Teach the persistent row index about every widget encountered,
             * including textless sprite widgets such as channel rank icons.
             */
            observeWidgetFromSurfaceScan(
                    surface,
                    root,
                    widget);

            final String semantic =
                    textNormalizer.normalizeSemantic(
                            widget.getText());

            if (semantic == null
                    || semantic.isEmpty())
            {
                return;
            }

            widgetsBySemantic
                    .computeIfAbsent(
                            semanticKey(
                                    semantic),
                            ignored -> new ArrayList<>())
                    .add(
                            widget);
        }

        private String semanticKey(
                String text)
        {
            return text.toLowerCase(
                    Locale.ROOT);
        }
    }

    /*
     * ================================================================
     * SURFACE
     * ================================================================
     */

    private Surface determineSurface(
            int scriptId,
            int parentWidgetId)
    {
        if (scriptId
                != FontMeasurementService.CHAT_BODY_SCRIPT)
        {
            return Surface.CHATBOX;
        }

        final Widget splitPrivate =
                client.getWidget(
                        InterfaceID.PM_CHAT,
                        0);

        if (splitPrivate != null
                && parentWidgetId
                == splitPrivate.getId())
        {
            return Surface.SPLIT_PRIVATE;
        }

        return Surface.CHATBOX;
    }

    /*
     * ================================================================
     * LIFECYCLE
     * ================================================================
     */

    @SuppressWarnings("deprecation")
    public void restoreNativePresentation()
    {
        if (nativeWidgetStates.isEmpty())
        {
            return;
        }

        for (Map.Entry<Widget, NativeWidgetState> entry
                : nativeWidgetStates.entrySet())
        {
            final Widget widget =
                    entry.getKey();

            final NativeWidgetState state =
                    entry.getValue();

            if (widget == null
                    || state == null)
            {
                continue;
            }

            boolean changed =
                    false;

            /*
             * Restore a field only when it still equals Chat XL's last-applied value.
             */
            if (state.fontIdCaptured
                    && widget.getFontId()
                    == state.appliedFontId
                    && widget.getFontId()
                    != state.nativeFontId)
            {
                widget.setFontId(
                        state.nativeFontId);

                changed =
                        true;
            }

            if (state.lineHeightCaptured
                    && widget.getLineHeight()
                    == state.appliedLineHeight
                    && widget.getLineHeight()
                    != state.nativeLineHeight)
            {
                widget.setLineHeight(
                        state.nativeLineHeight);

                changed =
                        true;
            }

            if (state.textCaptured
                    && sameText(
                    widget.getText(),
                    state.appliedText)
                    && !sameText(
                    widget.getText(),
                    state.nativeText))
            {
                widget.setText(
                        state.nativeText);

                changed =
                        true;
            }

            if (state.originalXCaptured
                    && widget.getOriginalX()
                    == state.appliedOriginalX
                    && widget.getOriginalX()
                    != state.nativeOriginalX)
            {
                widget.setOriginalX(
                        state.nativeOriginalX);

                changed =
                        true;
            }

            if (state.originalYCaptured
                    && widget.getOriginalY()
                    == state.appliedOriginalY
                    && widget.getOriginalY()
                    != state.nativeOriginalY)
            {
                widget.setOriginalY(
                        state.nativeOriginalY);

                changed =
                        true;
            }

            if (state.relativeYCaptured
                    && widget.getRelativeY()
                    == state.appliedRelativeY
                    && widget.getRelativeY()
                    != state.nativeRelativeY)
            {
                widget.setRelativeY(
                        state.nativeRelativeY);

                changed =
                        true;
            }

            if (state.originalWidthCaptured
                    && widget.getOriginalWidth()
                    == state.appliedOriginalWidth
                    && widget.getOriginalWidth()
                    != state.nativeOriginalWidth)
            {
                widget.setOriginalWidth(
                        state.nativeOriginalWidth);

                changed =
                        true;
            }

            if (state.originalHeightCaptured
                    && widget.getOriginalHeight()
                    == state.appliedOriginalHeight
                    && widget.getOriginalHeight()
                    != state.nativeOriginalHeight)
            {
                widget.setOriginalHeight(
                        state.nativeOriginalHeight);

                changed =
                        true;
            }

            if (changed)
            {
                widget.revalidate();
            }
        }

        nativeWidgetStates.clear();
    }

    public void reset()
    {
        pending =
                null;

        pendingFontProfile =
                null;

        pendingYOffsets.clear();

        rowIndexes.clear();
    }

    /*
     * Native and last-applied presentation values captured per field
     * for one Widget identity.
     */
    private static final class NativeWidgetState
    {
        private boolean fontIdCaptured;
        private int nativeFontId;
        private int appliedFontId;

        private boolean lineHeightCaptured;
        private int nativeLineHeight;
        private int appliedLineHeight;

        private boolean textCaptured;
        private String nativeText;
        private String appliedText;

        private boolean originalXCaptured;
        private int nativeOriginalX;
        private int appliedOriginalX;

        private boolean originalYCaptured;
        private int nativeOriginalY;
        private int appliedOriginalY;

        private boolean relativeYCaptured;
        private int nativeRelativeY;
        private int appliedRelativeY;

        private boolean originalWidthCaptured;
        private int nativeOriginalWidth;
        private int appliedOriginalWidth;

        private boolean originalHeightCaptured;
        private int nativeOriginalHeight;
        private int appliedOriginalHeight;
    }

    /*
     * Immutable configured font/profile pair.
     */
    private static final class ActiveFontState
    {
        private final ChatFont chatFont;

        private final ChatFontProfile fontProfile;

        private ActiveFontState(
                ChatFont chatFont,
                ChatFontProfile fontProfile)
        {
            this.chatFont =
                    chatFont;

            this.fontProfile =
                    fontProfile;
        }
    }

    /*
     * One delayed component-specific Y correction.
     *
     * Text corrections retain expected semantic text.
     * Sprite corrections retain an expected sprite ID.
     *
     * Exactly one guard is populated for each instance.
     */
    private static final class PendingYOffset
    {
        private final String expectedSemanticText;

        private final int expectedSpriteId;

        private final int yOffset;

        private PendingYOffset(
                String expectedSemanticText,
                int expectedSpriteId,
                int yOffset)
        {
            this.expectedSemanticText =
                    expectedSemanticText;

            this.expectedSpriteId =
                    expectedSpriteId;

            this.yOffset =
                    yOffset;
        }

        private static PendingYOffset forText(
                String expectedSemanticText,
                int yOffset)
        {
            return new PendingYOffset(
                    expectedSemanticText,
                    -1,
                    yOffset);
        }

        private static PendingYOffset forSprite(
                int expectedSpriteId,
                int yOffset)
        {
            return new PendingYOffset(
                    null,
                    expectedSpriteId,
                    yOffset);
        }

        private boolean matches(
                Widget widget,
                ChatTextNormalizer textNormalizer)
        {
            if (widget == null)
            {
                return false;
            }

            if (expectedSpriteId >= 0)
            {
                return widget.getSpriteId()
                        == expectedSpriteId;
            }

            if (expectedSemanticText == null)
            {
                return false;
            }

            final String currentSemanticText =
                    textNormalizer.normalizeSemantic(
                            widget.getText());

            return currentSemanticText != null
                    && currentSemanticText.equalsIgnoreCase(
                    expectedSemanticText);
        }
    }

    enum Surface
    {
        CHATBOX,
        SPLIT_PRIVATE
    }
}

package com.bigboldchat.chat;

import com.bigboldchat.debug.PerformanceMetrics;

import java.util.regex.Matcher;
import java.util.regex.Pattern;

import net.runelite.client.util.Text;

/**
 * Normalizes chat text for semantic comparison and font measurement.
 */
public final class ChatTextNormalizer
{
    private static final Pattern LINE_BREAK_PATTERN =
            Pattern.compile(
                    "<br\\s*/?>",
                    Pattern.CASE_INSENSITIVE);

    private static final Pattern IMAGE_PATTERN =
            Pattern.compile(
                    "<img=(\\d+)>",
                    Pattern.CASE_INSENSITIVE);

    private static final Pattern AT_PATTERN =
            Pattern.compile(
                    "<at>",
                    Pattern.CASE_INSENSITIVE);

    // Optional performance instrumentation; null when disabled.
    private final PerformanceMetrics performanceMetrics;

    public ChatTextNormalizer()
    {
        this(null);
    }

    public ChatTextNormalizer(
            PerformanceMetrics performanceMetrics)
    {
        this.performanceMetrics =
                performanceMetrics;
    }

    String normalizeSemantic(
            String text)
    {
        final long started =
                performanceMetrics != null
                        ? System.nanoTime()
                        : 0L;

        try
        {
            if (text == null)
            {
                return null;
            }

            /*
             * Most chat text contains no markup.
             */
            if (text.indexOf('<') < 0)
            {
                final String normalized =
                        text.indexOf('\u00A0') >= 0
                                ? text.replace(
                                '\u00A0',
                                ' ')
                                : text;

                return normalized.trim();
            }

            final String withLineBreaks =
                    LINE_BREAK_PATTERN
                            .matcher(
                                    text)
                            .replaceAll(
                                    "\n");

            final String withVisibleAtCharacters =
                    AT_PATTERN
                            .matcher(
                                    withLineBreaks)
                            .replaceAll(
                                    "@");

            final String semantic =
                    Text.removeTags(
                                    withVisibleAtCharacters)
                            .replace(
                                    '\u00A0',
                                    ' ')
                            .trim();

            if (!semantic.isEmpty())
            {
                return semantic;
            }

            // Keep image-only messages identifiable after markup is removed.
            return extractImages(
                    withVisibleAtCharacters);
        }
        finally
        {
            if (performanceMetrics != null)
            {
                performanceMetrics.recordNormalization(
                        System.nanoTime()
                                - started);
            }
        }
    }

    String measureSemantic(
            String text)
    {
        final long started =
                performanceMetrics != null
                        ? System.nanoTime()
                        : 0L;

        try
        {
            if (text == null)
            {
                return null;
            }

            /*
             * Keep inline image markup for font measurement.
             */
            if (text.indexOf('<') < 0)
            {
                final String normalized =
                        text.indexOf('\u00A0') >= 0
                                ? text.replace(
                                '\u00A0',
                                ' ')
                                : text;

                return normalized.trim();
            }

            final String withLineBreaks =
                    LINE_BREAK_PATTERN
                            .matcher(
                                    text)
                            .replaceAll(
                                    "\n");

            final String withVisibleAtCharacters =
                    AT_PATTERN
                            .matcher(
                                    withLineBreaks)
                            .replaceAll(
                                    "@");

            return withVisibleAtCharacters
                    .replace(
                            '\u00A0',
                            ' ')
                    .trim();
        }
        finally
        {
            if (performanceMetrics != null)
            {
                performanceMetrics.recordNormalization(
                        System.nanoTime()
                                - started);
            }
        }
    }

    String renderText(
            String text)
    {
        if (text == null
                || text.indexOf('<') < 0)
        {
            return text;
        }

        return AT_PATTERN
                .matcher(
                        text)
                .replaceAll(
                        "@");
    }

    /*
     * HELPERS
     */

    private String extractImages(
            String text)
    {
        if (text == null
                || text.isEmpty())
        {
            return "";
        }

        final Matcher matcher =
                IMAGE_PATTERN.matcher(
                        text);

        final StringBuilder images =
                new StringBuilder();

        while (matcher.find())
        {
            images.append(
                            "<img=")
                    .append(
                            matcher.group(
                                    1))
                    .append(
                            '>');
        }

        return images.toString();
    }
}

package com.bigboldchat.chat;

import com.bigboldchat.config.ChatFont;
import com.bigboldchat.debug.PerformanceMetrics;
import com.bigboldchat.fonts.ChatFontProfile;
import com.bigboldchat.fonts.ChatFontRegistry;

import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Locale;
import java.util.Map;

import net.runelite.api.Client;
import net.runelite.api.FontID;
import net.runelite.api.FontTypeFace;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.Widget;

/**
 * Measures chat text, wrapping, row allocation, and presentation geometry.
 *
 * Produces ConstructionMeasurement values consumed by FontLayoutService.
 * This service does not mutate widgets or script stacks.
 */
public final class FontMeasurementService
{
    static final int GAME_BODY_SCRIPT = 199;
    static final int CHAT_BODY_SCRIPT = 203;
    static final int CHANNEL_BODY_SCRIPT = 4483;

    /*
     * Native OS separation between:
     *      [username] -> [message body]
     */
    private static final int BODY_GAP = 3;

    /*
     * Native Script 4483 rank-icon geometry:
     *      [channel] +1px [icon] +1px [username]:
     */
    private static final int RANK_ICON_GAP = 1;

    private final Client client;
    private final ChatTextNormalizer textNormalizer;

    // Optional performance instrumentation; null when disabled.
    private final PerformanceMetrics performanceMetrics;

    /*
     * Cache resolved fonts for the current plugin session.
     * Failed resolutions are retried on the next request.
     */
    private final Map<Integer, FontTypeFace> fontCache = new HashMap<>();

    public FontMeasurementService(
            Client client)
    {
        this(
                client,
                new ChatTextNormalizer(),
                null);
    }

    public FontMeasurementService(
            Client client,
            PerformanceMetrics performanceMetrics)
    {
        this(
                client,
                new ChatTextNormalizer(
                        performanceMetrics),
                performanceMetrics);
    }

    public FontMeasurementService(
            Client client,
            ChatTextNormalizer textNormalizer,
            PerformanceMetrics performanceMetrics)
    {
        this.client =
                client;

        this.textNormalizer =
                textNormalizer != null
                        ? textNormalizer
                        : new ChatTextNormalizer(
                        performanceMetrics);

        this.performanceMetrics =
                performanceMetrics;
    }

    boolean supportsScript(
            int scriptId)
    {
        return scriptId
                == GAME_BODY_SCRIPT
                || scriptId
                == CHAT_BODY_SCRIPT
                || scriptId
                == CHANNEL_BODY_SCRIPT;
    }

    ConstructionMeasurement measure(
            int scriptId,
            ChatFont selectedChatFont,
            ChatFontProfile fontProfile)
    {
        if (!supportsScript(
                scriptId)
                || selectedChatFont == null
                || fontProfile == null)
        {
            return null;
        }

        final Object[] objectStack =
                client.getObjectStack();

        final int objectStackSize =
                client.getObjectStackSize();

        final String rawBody =
                findBody(
                        objectStack,
                        objectStackSize);

        if (rawBody == null)
        {
            return null;
        }

        final String semanticBody =
                textNormalizer.normalizeSemantic(
                        rawBody);

        if (semanticBody == null
                || semanticBody.isEmpty())
        {
            return null;
        }

        /*
         * FontID 1446 renders ':' incorrectly.
         *
         * Keep native text unchanged for correlation and replace ':' only in
         * the selected text that Chat XL measures and renders.
         */
        final boolean replaceMalformedColons =
                selectedChatFont
                        == ChatFont.VERDANA_13_BOLD;

        final String visibleRawBodyText =
                textNormalizer.renderText(
                        rawBody);

        final String selectedRawBodyText =
                replaceMalformedColons
                        ? replaceVerdana13BoldColons(
                        visibleRawBodyText)
                        : visibleRawBodyText;

        // Preserve inline images while measuring wrapping.
        final String measurementBody =
                textNormalizer.measureSemantic(
                        rawBody);

        final String selectedMeasurementBody =
                textNormalizer.measureSemantic(
                        selectedRawBodyText);

        if (measurementBody == null || selectedMeasurementBody == null)
        {
            return null;
        }

        final int[] intStack =
                client.getIntStack();

        final int intStackSize =
                client.getIntStackSize();

        if (intStack == null
                || intStackSize < 11
                || intStackSize > intStack.length)
        {
            return null;
        }

        /*
         * Common trailing Script 199 / 203 / 4483 construction payload:
         *
         * [0]  row / order
         * [1]  line widget
         * [2]  parent widget
         * [3]  right boundary
         * [4]  left boundary
         * [5]  vertical / line-height construction input
         * [6]  row Y
         * [7]  unknown - preserve native
         * [8]  sender / prefix width
         * [9]  color
         * [10] shadow
         */
        final int rowValueIndex =
                intStackSize - 11;

        final int lineWidgetIndex =
                intStackSize - 10;

        final int parentWidgetIndex =
                intStackSize - 9;

        final int rightBoundaryIndex =
                intStackSize - 8;

        final int leftBoundaryIndex =
                intStackSize - 7;

        final int verticalValueIndex =
                intStackSize - 6;

        final int rowYIndex =
                intStackSize - 5;

        final int argument7Index =
                intStackSize - 4;

        final int senderWidthIndex =
                intStackSize - 3;

        final int colorIndex =
                intStackSize - 2;

        final int shadowIndex =
                intStackSize - 1;

        final int lineWidgetId =
                intStack[lineWidgetIndex];

        final int parentWidgetId =
                intStack[parentWidgetIndex];

        final int rightBoundary =
                intStack[rightBoundaryIndex];

        final int leftBoundary =
                intStack[leftBoundaryIndex];

        final int nativeLineHeight =
                intStack[verticalValueIndex];

        final int nativeRowY =
                intStack[rowYIndex];

        final int nativeArgument7 =
                intStack[argument7Index];

        final int nativeSenderWidth =
                intStack[senderWidthIndex];

        if (nativeLineHeight <= 0)
        {
            return null;
        }

        final Widget lineWidget =
                client.getWidget(
                        lineWidgetId);

        if (lineWidget == null)
        {
            return null;
        }

        final FontTypeFace nativeFont =
                resolveFont(
                        FontID.PLAIN_12);

        final FontTypeFace selectedFont =
                resolveFont(
                        selectedChatFont.getFontId());

        final ChatFontProfile nativeFontProfile =
                ChatFontRegistry.get(
                        ChatFont.PLAIN_12);

        if (nativeFont == null
                || selectedFont == null
                || nativeFontProfile == null)
        {
            return null;
        }

        final List<String> rawPrefixComponents =
                scriptId == GAME_BODY_SCRIPT
                        ? new ArrayList<>()
                        : findPrefixComponents(
                        objectStack,
                        objectStackSize,
                        semanticBody);

        /*
         * Script 199 is the ordinary prefix-less GAME / system-message
         * constructor.
         *
         * Script 203 requires a textual prefix.
         *
         * Script 4483 can legitimately provide empty title / sender
         * components for Clan / Guest Clan system messages.
         */
        if (scriptId == CHAT_BODY_SCRIPT
                && rawPrefixComponents.isEmpty())
        {
            return null;
        }

        final int lineX =
                lineWidget.getOriginalX();

        int nativePrefixWidth =
                0;

        int selectedPrefixLayoutWidth =
                0;

        ChannelPrefixLayout nativeChannelLayout =
                null;

        ChannelPrefixLayout selectedChannelLayout =
                null;

        int nativeBodyX;
        int selectedBodyX;

        /*
         * Script 203 keeps its native/raw prefix for correlation while the
         * selected presentation may use a separately spaced raw prefix.
         *
         * This is primarily used by Friends Chat, where the rank icon is inline
         * markup inside the same prefix widget as the channel name and username.
         */
        String selectedRawPrefixText =
                null;

        if (scriptId == GAME_BODY_SCRIPT)
        {
            /*
             * Script 199 is prefix-less and uses the full construction span.
             * Preserve its native horizontal geometry.
             */
            nativeBodyX =
                    leftBoundary;

            selectedBodyX =
                    leftBoundary;
        }
        else if (scriptId == CHAT_BODY_SCRIPT)
        {
            final String rawPrefix =
                    rawPrefixComponents.get(
                            rawPrefixComponents.size() - 1);

            // Measure native geometry from the unmodified prefix.
            nativePrefixWidth =
                    nativeFont.getTextWidth(
                            normalizeRawForMeasurement(
                                    rawPrefix));

            /*
             * Keep the raw Friends Chat prefix for correlation and build a separate
             * rendered prefix with configured inline-icon spacing.
             */
            selectedRawPrefixText =
                    isFriendsChatPrefix(
                            rawPrefix)
                            ? applyInlineIconUsernameSpacing(
                            rawPrefix,
                            fontProfile.getFriendsChatPlayerIconSpacing(),
                            '\u00A0')
                            : rawPrefix;

            /*
             * Replace malformed FontID 1446 colons in the selected prefix only.
             */
            if (replaceMalformedColons)
            {
                selectedRawPrefixText =
                        replaceVerdana13BoldColons(
                                selectedRawPrefixText);
            }

            selectedPrefixLayoutWidth =
                    selectedFont.getTextWidth(
                            normalizeRawForMeasurement(
                                    selectedRawPrefixText));

            nativeBodyX =
                    lineX
                            + nativePrefixWidth
                            + BODY_GAP;

            selectedBodyX =
                    lineX
                            + selectedPrefixLayoutWidth
                            + BODY_GAP;
        }
        else
        {
            nativeChannelLayout =
                    measureChannelPrefixLayout(
                            nativeFont,
                            rawPrefixComponents,
                            intStack,
                            intStackSize,
                            lineX,
                            false,
                            0,
                            0,
                            nativeFontProfile.getAccountBuildIconPadding(),
                            0);

            selectedChannelLayout =
                    measureChannelPrefixLayout(
                            selectedFont,
                            rawPrefixComponents,
                            intStack,
                            intStackSize,
                            lineX,
                            replaceMalformedColons,
                            fontProfile.getRankIconRightAdjustment(),
                            fontProfile.getRankIconSizeAdjustment(),
                            fontProfile.getAccountBuildIconPadding(),
                            fontProfile.getChannelAccountBuildIconSpacing());

            if (nativeChannelLayout == null
                    || selectedChannelLayout == null)
            {
                return null;
            }

            nativeBodyX =
                    nativeChannelLayout.bodyX;

            selectedBodyX =
                    selectedChannelLayout.bodyX;
        }

        final int nativeBodyWidth =
                rightBoundary
                        - nativeBodyX;

        final int selectedBodyWidth =
                rightBoundary
                        - selectedBodyX;

        if (nativeBodyWidth <= 0
                || selectedBodyWidth <= 0)
        {
            return null;
        }

        final int nativeLines =
                calculateWrappedLineCount(
                        nativeFont,
                        measurementBody,
                        nativeBodyWidth);

        final int selectedLines =
                calculateWrappedLineCount(
                        selectedFont,
                        selectedMeasurementBody,
                        selectedBodyWidth);

        if (nativeLines <= 0
                || selectedLines <= 0)
        {
            return null;
        }

        // Apply the selected profile's line-height adjustment.
        final int lineHeightAdjustment =
                fontProfile
                        .getLineHeightAdjustment();

        final int selectedLineHeight =
                Math.max(
                        1,
                        nativeLineHeight
                                + lineHeightAdjustment);

        final int rowYOffset =
                fontProfile
                        .getRowYOffset();

        /*
         * Apply PRIVATE_CHAT_GAP to Split Private's bottom-relative row Y.
         * Positive increases the gap; negative reduces it.
         */
        final int privateChatGap =
                isSplitPrivateChatConstruction(
                        scriptId,
                        parentWidgetId)
                        ? fontProfile.getPrivateChatGap()
                        : 0;

        final int selectedRowY =
                nativeRowY
                        + rowYOffset
                        + privateChatGap;

        /*
         * Compensate construction height for native and selected wrapped-line counts.
         */
        final int desiredHeight =
                selectedLines
                        * selectedLineHeight;

        final int injectedValue =
                ceilDiv(
                        desiredHeight,
                        nativeLines);

        if (injectedValue <= 0)
        {
            return null;
        }

        final int allocatedHeight =
                nativeLines
                        * injectedValue;

        final ConstructionMeasurement measurement =
                new ConstructionMeasurement();

        measurement.scriptId =
                scriptId;

        measurement.semanticBody =
                semanticBody;

        measurement.selectedRawBodyText =
                selectedRawBodyText;

        measurement.selectedChatFont =
                selectedChatFont;

        measurement.selectedFontId =
                selectedChatFont.getFontId();

        measurement.rawPrefixComponents =
                new ArrayList<>(
                        rawPrefixComponents);

        /*
         * Script 203 keeps the selected/rendered raw prefix separately from the
         * native raw components used for correlation.
         */
        measurement.selectedRawPrefixText =
                selectedRawPrefixText;

        measurement.rowValueIndex =
                rowValueIndex;

        measurement.verticalValueIndex =
                verticalValueIndex;

        measurement.rowYIndex =
                rowYIndex;

        measurement.argument7Index =
                argument7Index;

        measurement.senderWidthIndex =
                senderWidthIndex;

        measurement.lineWidgetId =
                lineWidgetId;

        measurement.parentWidgetId =
                parentWidgetId;

        measurement.leftBoundary =
                leftBoundary;

        measurement.rightBoundary =
                rightBoundary;

        measurement.lineX =
                lineX;

        measurement.nativeLineHeight =
                nativeLineHeight;

        measurement.lineHeightAdjustment =
                lineHeightAdjustment;

        measurement.selectedLineHeight =
                selectedLineHeight;

        measurement.nativeRowY =
                nativeRowY;

        measurement.rowYOffset =
                rowYOffset;

        measurement.selectedRowY =
                selectedRowY;

        measurement.channelTextYOffset =
                fontProfile
                        .getChannelTextYOffset();

        measurement.rankIconRightAdjustment =
                fontProfile
                        .getRankIconRightAdjustment();

        measurement.rankIconSizeAdjustment =
                fontProfile
                        .getRankIconSizeAdjustment();

        measurement.rankIconYOffset =
                fontProfile
                        .getChannelRankIconYOffset();

        measurement.accountBuildIconPadding =
                fontProfile
                        .getAccountBuildIconPadding();

        measurement.nativeArgument7 =
                nativeArgument7;

        measurement.nativeSenderWidth =
                nativeSenderWidth;

        measurement.nativeColor =
                intStack[colorIndex];

        measurement.nativeShadow =
                intStack[shadowIndex];

        measurement.nativePrefixWidth =
                nativePrefixWidth;

        measurement.selectedPrefixLayoutWidth =
                selectedPrefixLayoutWidth;

        measurement.nativeChannelLayout =
                nativeChannelLayout;

        measurement.selectedChannelLayout =
                selectedChannelLayout;

        measurement.nativeBodyX =
                nativeBodyX;

        measurement.nativeBodyWidth =
                nativeBodyWidth;

        measurement.selectedBodyX =
                selectedBodyX;

        measurement.selectedBodyWidth =
                selectedBodyWidth;

        measurement.nativeLines =
                nativeLines;

        measurement.selectedLines =
                selectedLines;

        measurement.desiredHeight =
                desiredHeight;

        measurement.injectedValue =
                injectedValue;

        measurement.allocatedHeight =
                allocatedHeight;

        return measurement;
    }

    /*
     * ================================================================
     * PRIVATE CHAT
     * ================================================================
     */
    private boolean isSplitPrivateChatConstruction(
            int scriptId,
            int parentWidgetId)
    {
        if (scriptId != CHAT_BODY_SCRIPT)
        {
            return false;
        }

        final Widget splitPrivate =
                client.getWidget(
                        InterfaceID.PM_CHAT,
                        0);

        return splitPrivate != null
                && parentWidgetId
                == splitPrivate.getId();
    }

    /*
     * ================================================================
     * CHANNEL / RANK-ICON MEASUREMENT
     * ================================================================
     */
    private ChannelPrefixLayout measureChannelPrefixLayout(
            FontTypeFace font,
            List<String> rawPrefixComponents,
            int[] intStack,
            int intStackSize,
            int lineX,
            boolean replaceMalformedColons,
            int rankIconRightAdjustment,
            int rankIconSizeAdjustment,
            int accountBuildIconPadding,
            int inlineIconUsernameSpacing)
    {
        if (font == null
                || rawPrefixComponents == null
                || intStack == null)
        {
            return null;
        }

        final ChannelPrefixLayout layout =
                new ChannelPrefixLayout();

        layout.titleX =
                lineX;

        final String rawTitleText =
                rawPrefixComponents.size() > 0
                        ? rawPrefixComponents.get(
                        0)
                        : "";

        layout.titleText =
                textNormalizer.normalizeSemantic(
                        rawTitleText);

        layout.renderedTitleText =
                replaceMalformedColons
                        ? replaceVerdana13BoldColons(
                        rawTitleText)
                        : rawTitleText;

        final String rawSenderText =
                rawPrefixComponents.size() > 1
                        ? rawPrefixComponents.get(
                        1)
                        : "";

        /*
         * Preserve the native sender semantic for correlation.
         */
        layout.senderText =
                textNormalizer.normalizeSemantic(
                        rawSenderText);

        /*
         * The rendered sender may contain additional visible spacing after the
         * final inline account/build icon.
         *
         * Example:
         *
         *     native:   <img=2>Username:
         *     selected: <img=2> Username:
         */
        layout.renderedSenderText =
                applyInlineIconUsernameSpacing(
                        rawSenderText,
                        inlineIconUsernameSpacing,
                        ' ');

        if (replaceMalformedColons)
        {
            layout.renderedSenderText =
                    replaceVerdana13BoldColons(
                            layout.renderedSenderText);
        }

        if (layout.titleText == null)
        {
            layout.titleText =
                    "";
        }

        if (layout.senderText == null)
        {
            layout.senderText =
                    "";
        }

        layout.hasTitle =
                !layout.titleText.isEmpty();

        layout.hasSender =
                !layout.senderText.isEmpty();

        if (layout.hasTitle)
        {
            layout.titleWidth =
                    font.getTextWidth(
                            normalizeRawForMeasurement(
                                    layout.renderedTitleText));
        }

        if (layout.hasSender)
        {
            layout.senderWidth =
                    font.getTextWidth(
                            normalizeRawForMeasurement(
                                    layout.renderedSenderText));
        }

        /*
         * Read optional rank sprite ID, width, and height
         * immediately before the common Script-4483 payload.
         */
        final int commonPayloadStart =
                intStackSize - 11;

        if (layout.hasSender
                && commonPayloadStart >= 3)
        {
            final int spriteIdCandidate =
                    intStack[commonPayloadStart - 3];

            final int widthCandidate =
                    intStack[commonPayloadStart - 2];

            final int heightCandidate =
                    intStack[commonPayloadStart - 1];

            if (spriteIdCandidate >= 0
                    && widthCandidate > 0
                    && widthCandidate <= 32
                    && heightCandidate > 0
                    && heightCandidate <= 32)
            {
                layout.rankIconSpriteId =
                        spriteIdCandidate;

                layout.rankIconWidth =
                        Math.max(
                                1,
                                widthCandidate
                                        + rankIconSizeAdjustment);

                layout.rankIconHeight =
                        Math.max(
                                1,
                                heightCandidate
                                        + rankIconSizeAdjustment);
            }
        }

        /*
         * Inline account/build icons are measured as part of sender text.
         *
         * CHANNEL_ACCOUNT_BUILD_ICON_SPACING controls icon-to-name spacing.
         * ACCOUNT_BUILD_ICON_PADDING reserves additional sender layout width.
         */
        if (layout.hasSender
                && hasAccountBuildIcon(
                rawSenderText))
        {
            layout.senderWidth +=
                    accountBuildIconPadding;
        }

        int cursor =
                lineX;

        if (layout.hasTitle)
        {
            cursor +=
                    layout.titleWidth;
        }

        if (layout.hasSender)
        {
            if (layout.rankIconWidth > 0)
            {
                /*
                 * Native:
                 *
                 * title -> 1px -> icon -> 1px -> sender
                 */
                if (layout.hasTitle)
                {
                    cursor +=
                            RANK_ICON_GAP;
                }

                layout.rankIconX =
                        cursor;

                cursor +=
                        layout.rankIconWidth;

                cursor +=
                        RANK_ICON_GAP;

                /*
                 * Enforce minimum spacing after the final inline image before the username.
                 *
                 * The caller supplies the spacing character. Existing whitespace counts
                 * toward the minimum, and consecutive inline images are not separated.
                 */
                cursor +=
                        rankIconRightAdjustment;
            }
            else if (layout.hasTitle)
            {
                cursor +=
                        BODY_GAP;
            }

            layout.senderX =
                    cursor;

            cursor +=
                    layout.senderWidth;

            cursor +=
                    BODY_GAP;
        }
        else if (layout.hasTitle)
        {
            // Title-only Clan / Guest Clan system message.
            cursor +=
                    BODY_GAP;
        }

        // If both title and sender are empty, the body naturally begins at lineX.
        layout.bodyX =
                cursor;

        return layout;
    }

    /*
     * ================================================================
     * VERDANA 13 BOLD CORRECTION
     * ================================================================
     */

    /*
     * FontID 1446 renders ':' incorrectly.
     *
     * This helper is used only for selected Verdana 13 Bold text.
     * Native text remains unchanged for widget correlation.
     */
    private String replaceVerdana13BoldColons(
            String text)
    {
        if (text == null
                || text.isEmpty())
        {
            return text;
        }

        return text.replace(
                ':',
                '-');
    }

    /*
     * ================================================================
     * FONT RESOLUTION
     * ================================================================
     */

    private FontTypeFace resolveFont(
            int fontId)
    {
        final FontTypeFace cachedFont =
                fontCache.get(
                        fontId);

        if (cachedFont != null)
        {
            if (performanceMetrics != null)
            {
                performanceMetrics.recordFontCacheHit();
            }

            return cachedFont;
        }

        final long started =
                performanceMetrics != null
                        ? System.nanoTime()
                        : 0L;

        try
        {
            final Widget probe =
                    client.getWidget(
                            InterfaceID.Chatbox.INPUT);

            if (probe == null)
            {
                return null;
            }

            final int originalFontId =
                    probe.getFontId();

            final FontTypeFace resolvedFont;

            try
            {
                probe.setFontId(
                        fontId);

                resolvedFont =
                        probe.getFont();
            }
            finally
            {
                probe.setFontId(
                        originalFontId);
            }

            if (resolvedFont != null)
            {
                fontCache.put(
                        fontId,
                        resolvedFont);
            }

            return resolvedFont;
        }
        finally
        {
            if (performanceMetrics != null)
            {
                performanceMetrics.recordFontCacheMiss(
                        System.nanoTime()
                                - started);
            }
        }
    }

    /*
     * ================================================================
     * OBJECT-STACK EXTRACTION
     * ================================================================
     */
    private String findBody(
            Object[] stack,
            int size)
    {
        if (stack == null
                || size <= 0)
        {
            return null;
        }

        final int safeSize =
                Math.min(
                        size,
                        stack.length);

        for (int i = safeSize - 1;
             i >= 0;
             i--)
        {
            final Object value =
                    stack[i];

            if (!(value instanceof String))
            {
                continue;
            }

            final String raw =
                    (String) value;

            final String semantic =
                    textNormalizer.normalizeSemantic(
                            raw);

            if (semantic == null
                    || semantic.isEmpty())
            {
                continue;
            }

            return raw;
        }

        return null;
    }

    private List<String> findPrefixComponents(
            Object[] stack,
            int size,
            String semanticBody)
    {
        final List<String> result =
                new ArrayList<>();

        if (stack == null
                || size <= 0
                || semanticBody == null)
        {
            return result;
        }

        final int safeSize =
                Math.min(
                        size,
                        stack.length);

        for (int i = 0;
             i < safeSize;
             i++)
        {
            final Object value =
                    stack[i];

            if (!(value instanceof String))
            {
                continue;
            }

            final String raw =
                    (String) value;

            final String semantic =
                    textNormalizer.normalizeSemantic(
                            raw);

            if (semantic == null)
            {
                continue;
            }

            if (semantic.equalsIgnoreCase(
                    semanticBody))
            {
                break;
            }

            /*
             * Preserve empty prefix components.
             *
             * Script 4483 uses them to represent title-only and
             * prefix-less system rows.
             */
            result.add(
                    raw);
        }

        return result;
    }

    private boolean hasAccountBuildIcon(
            String rawSenderText)
    {
        if (rawSenderText == null
                || rawSenderText.isEmpty())
        {
            return false;
        }

        return rawSenderText
                .toLowerCase(
                        Locale.ROOT)
                .contains(
                        "<img=");
    }

    /*
     * Add visible spacing between the final inline image tag and the
     * username that follows it.
     *
     * The caller supplies the actual spacing character because Chat XL uses
     * different spacing characters for the two supported inline-icon cases:
     *
     *     Friends Chat player/rank icon:
     *         \u00A0  non-breaking space
     *
     *     Clan / Guest Clan account-build icon:
     *         \u0020  normal space
     *
     * If multiple inline images occur before the username, only the final
     * image receives the username gap:
     *
     *     <img=67><img=2>PlayerName:
     *
     * becomes:
     *
     *     <img=67><img=2> PlayerName:
     *
     * rather than inserting spacing between the consecutive icons.
     *
     * Existing whitespace immediately after the final image counts toward
     * the configured minimum, which keeps repeated processing idempotent.
     */
    private String applyInlineIconUsernameSpacing(
            String rawText,
            int spacing,
            char spacingCharacter)
    {
        if (rawText == null
                || rawText.isEmpty()
                || spacing <= 0)
        {
            return rawText;
        }

        final String lower =
                rawText.toLowerCase(
                        Locale.ROOT);

        final int imageStart =
                lower.lastIndexOf(
                        "<img=");

        if (imageStart < 0)
        {
            return rawText;
        }

        final int imageEnd =
                rawText.indexOf(
                        '>',
                        imageStart);

        if (imageEnd < 0
                || imageEnd
                >= rawText.length() - 1)
        {
            return rawText;
        }

        int existingSpacing =
                0;

        for (int i = imageEnd + 1;
             i < rawText.length();
             i++)
        {
            final char ch =
                    rawText.charAt(
                            i);

            if (ch == ' '
                    || ch == '\u00A0'
                    || ch == '\t')
            {
                existingSpacing++;

                continue;
            }

            break;
        }

        final int spacingToAdd =
                Math.max(
                        0,
                        spacing
                                - existingSpacing);

        if (spacingToAdd == 0)
        {
            return rawText;
        }

        final StringBuilder gap =
                new StringBuilder(
                        spacingToAdd);

        for (int i = 0;
             i < spacingToAdd;
             i++)
        {
            gap.append(
                    spacingCharacter);
        }

        return rawText.substring(
                0,
                imageEnd + 1)
                + gap
                + rawText.substring(
                imageEnd + 1);
    }

    /*
     * Script 203 is used by several chat surfaces.
     *
     * Friends Chat is identified by its bracketed combined prefix:
     *
     *     [Friends Chat] <img=rank>Username:
     */
    private boolean isFriendsChatPrefix(
            String rawPrefix)
    {
        final String semanticPrefix =
                textNormalizer.normalizeSemantic(
                        rawPrefix);

        if (semanticPrefix == null
                || semanticPrefix.length() < 3
                || semanticPrefix.charAt(0) != '[')
        {
            return false;
        }

        final int closingBracket =
                semanticPrefix.indexOf(
                        ']');

        return closingBracket > 0
                && closingBracket
                < semanticPrefix.length() - 1;
    }

    /*
     * ================================================================
     * TEXT NORMALIZATION
     * ================================================================
     */

    private String normalizeRawForMeasurement(
            String text)
    {
        if (text == null)
        {
            return "";
        }

        return text
                .replace(
                        '\u00A0',
                        ' ');
    }

    /*
     * ================================================================
     * WRAPPING / HEIGHT
     * ================================================================
     */
    private int calculateWrappedLineCount(
            FontTypeFace font,
            String text,
            int maxWidth)
    {
        if (font == null
                || maxWidth <= 0
                || text == null
                || text.isEmpty())
        {
            return 1;
        }

        final String normalized =
                text
                        .replace(
                                "\r\n",
                                "\n")
                        .replace(
                                '\r',
                                '\n');

        final String[] explicitLines =
                normalized.split(
                        "\n",
                        -1);

        int totalLines =
                0;

        for (String explicitLine : explicitLines)
        {
            totalLines +=
                    calculateSingleParagraphLines(
                            font,
                            explicitLine,
                            maxWidth);
        }

        return Math.max(
                1,
                totalLines);
    }

    int calculateSingleParagraphLines(
            FontTypeFace font,
            String text,
            int maxWidth)
    {
        if (text == null
                || text.isEmpty())
        {
            return 1;
        }

        if (font.getTextWidth(
                text) <= maxWidth)
        {
            return 1;
        }

        final String trimmed =
                text.trim();

        if (trimmed.isEmpty())
        {
            return 1;
        }

        final String[] words =
                trimmed.split(
                        "\\s+");

        int lines =
                1;

        String currentLine =
                "";

        for (String word : words)
        {
            if (word.isEmpty())
            {
                continue;
            }

            /*
             * Don't hard-wrap one uninterrupted token character by character.
             * This applies uniformly to letters, digits, punctuation, and symbols.
             */
            if (font.getTextWidth(
                    word) > maxWidth)
            {
                if (!currentLine.isEmpty())
                {
                    lines++;
                }

                currentLine =
                        word;

                continue;
            }

            if (currentLine.isEmpty())
            {
                currentLine =
                        word;

                continue;
            }

            final String candidate =
                    currentLine
                            + " "
                            + word;

            if (font.getTextWidth(
                    candidate) <= maxWidth)
            {
                currentLine =
                        candidate;
            }
            else
            {
                lines++;

                currentLine =
                        word;
            }
        }

        return Math.max(
                1,
                lines);
    }

    private int ceilDiv(
            int numerator,
            int denominator)
    {
        if (denominator <= 0)
        {
            return numerator;
        }

        return (numerator
                + denominator
                - 1)
                / denominator;
    }

